{
  "name": "Financeira 12 Meses",
  "description": "Um aplicativo de organização financeira simples e eficiente focado em planejamento de 12 meses, dividido por blocos de renda, cartões, contas fixas, variáveis e lazer, com diagnósticos de saúde financeira baseados em percentuais ideais."
}

export enum CategoryType {
  INCOME = 'Renda',
  CREDIT_CARD = 'Cartão de Crédito',
  FIXED_EXPENSE = 'Contas Fixas',
  VARIABLE_EXPENSE = 'Contas Variáveis',
  PERSONAL_LEISURE = 'Lazer e Gastos Pessoais'
}

export interface MonthData {
  monthName: string;
  year: number;
}

export interface FinanceItem {
  id: string;
  description: string;
  category: CategoryType;
  values: number[]; // 12 months
  paidStatus: boolean[]; // 12 months
}

export interface SummaryData {
  totalIncome: number;
  totalCreditCard: number;
  totalFixed: number;
  totalVariable: number;
  totalLeisure: number;
  totalCost: number;
  balance: number;
  accumulated: number;
}

export const MONTHS_BR = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];

export const IDEAL_LIMITS = {
  FIXED: 0.55,    // 55%
  EDUCATION: 0.10, // 10% (Included in fixed/variable usually)
  SAVINGS: 0.20,  // 20%
  LEISURE: 0.15   // 15%
};

export const getNext12Months = () => {
  const result = [];
  const now = new Date();
  for (let i = 0; i < 12; i++) {
    const d = new Date(now.getFullYear(), now.getMonth() + i, 1);
    result.push({
      monthName: MONTHS_BR[d.getMonth()],
      year: d.getFullYear(),
      index: d.getMonth()
    });
  }
  return result;
};

export const formatCurrency = (value: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);
};

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';
import { CategoryType, FinanceItem } from '../types';
import { formatCurrency } from '../constants';

interface BlockSectionProps {
  title: string;
  category: CategoryType;
  items: FinanceItem[];
  months: any[];
  onAddItem: (category: CategoryType) => void;
  onUpdateValue: (id: string, monthIdx: number, value: string) => void;
  onTogglePaid: (id: string, monthIdx: number) => void;
  onRemoveItem: (id: string) => void;
  onUpdateDescription: (id: string, desc: string) => void;
}

const BlockSection: React.FC<BlockSectionProps> = ({
  title,
  category,
  items,
  months,
  onAddItem,
  onUpdateValue,
  onTogglePaid,
  onRemoveItem,
  onUpdateDescription
}) => {
  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden mb-8">
      <div className="bg-gray-800 p-4 flex justify-between items-center">
        <h3 className="text-white font-bold text-lg uppercase tracking-wider">{title}</h3>
        <button 
          onClick={() => onAddItem(category)}
          className="bg-green-600 hover:bg-green-500 text-white px-3 py-1 rounded text-sm transition-colors flex items-center gap-2"
        >
          <i className="fas fa-plus"></i> Adicionar
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="bg-gray-100 text-gray-700 uppercase font-semibold">
            <tr>
              <th className="p-3 border-b min-w-[200px]">Descrição</th>
              {months.map((m, idx) => (
                <th key={idx} className="p-3 border-b text-center min-w-[120px] border-l">
                  {m.monthName}
                </th>
              ))}
              <th className="p-3 border-b w-10"></th>
            </tr>
          </thead>
          <tbody>
            {items.map((item) => (
              <tr key={item.id} className="border-b hover:bg-gray-50 transition-colors">
                <td className="p-2">
                  <input
                    type="text"
                    value={item.description}
                    onChange={(e) => onUpdateDescription(item.id, e.target.value)}
                    className="w-full bg-transparent border-b border-transparent focus:border-blue-500 outline-none p-1"
                    placeholder="Ex: Aluguel"
                  />
                </td>
                {item.values.map((val, mIdx) => (
                  <td key={mIdx} className={`p-2 border-l text-center ${item.paidStatus[mIdx] ? 'bg-green-50' : ''}`}>
                    <div className="flex flex-col gap-1 items-center">
                      <input
                        type="number"
                        value={val || ''}
                        onChange={(e) => onUpdateValue(item.id, mIdx, e.target.value)}
                        className={`w-full text-center bg-transparent border rounded p-1 focus:ring-1 focus:ring-blue-400 outline-none ${item.paidStatus[mIdx] ? 'border-green-300 text-green-700 font-medium' : 'border-gray-200'}`}
                        placeholder="0,00"
                      />
                      {category !== CategoryType.INCOME && (
                        <button
                          onClick={() => onTogglePaid(item.id, mIdx)}
                          className={`text-[10px] px-2 py-0.5 rounded-full border transition-all ${
                            item.paidStatus[mIdx] 
                            ? 'bg-green-600 text-white border-green-600' 
                            : 'bg-white text-gray-400 border-gray-300 hover:border-green-500 hover:text-green-500'
                          }`}
                        >
                          {item.paidStatus[mIdx] ? 'PAGO' : 'PENDENTE'}
                        </button>
                      )}
                    </div>
                  </td>
                ))}
                <td className="p-2 text-center">
                  <button 
                    onClick={() => onRemoveItem(item.id)}
                    className="text-gray-300 hover:text-red-500 transition-colors"
                  >
                    <i className="fas fa-trash-alt"></i>
                  </button>
                </td>
              </tr>
            ))}
            {items.length === 0 && (
              <tr>
                <td colSpan={months.length + 2} className="p-8 text-center text-gray-400 italic">
                  Nenhum item adicionado nesta categoria.
                </td>
              </tr>
            )}
          </tbody>
          <tfoot className="bg-gray-50 font-bold">
            <tr>
              <td className="p-3">SUBTOTAL</td>
              {months.map((_, mIdx) => {
                const total = items.reduce((acc, item) => acc + (item.values[mIdx] || 0), 0);
                return (
                  <td key={mIdx} className="p-3 text-center border-l text-blue-700">
                    {formatCurrency(total)}
                  </td>
                );
              })}
              <td></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

export default BlockSection;

import React from 'react';
import { SummaryData } from '../types';
import { IDEAL_LIMITS, formatCurrency } from '../constants';

interface DiagnosisProps {
  summary: SummaryData;
  monthName: string;
}

const Diagnosis: React.FC<DiagnosisProps> = ({ summary, monthName }) => {
  const { totalIncome, totalFixed, totalLeisure, balance } = summary;

  const fixedPercent = totalIncome > 0 ? (totalFixed / totalIncome) : 0;
  const leisurePercent = totalIncome > 0 ? (totalLeisure / totalIncome) : 0;

  const isFixedOk = fixedPercent <= IDEAL_LIMITS.FIXED;
  const isLeisureOk = leisurePercent <= IDEAL_LIMITS.LEISURE;
  const isBalanceOk = balance >= 0;

  return (
    <div className="bg-blue-50 border border-blue-200 rounded-xl p-6 mb-8">
      <div className="flex items-center gap-3 mb-4">
        <i className="fas fa-stethoscope text-blue-600 text-2xl"></i>
        <h3 className="text-xl font-bold text-blue-900">Diagnóstico Financeiro - {monthName}</h3>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Fixed Costs Diagnosis */}
        <div className={`p-4 rounded-lg border ${isFixedOk ? 'bg-green-100 border-green-200' : 'bg-red-100 border-red-200'}`}>
          <div className="flex justify-between items-center mb-2">
            <span className="font-semibold text-sm uppercase">Custos Fixos</span>
            <span className={`text-xs px-2 py-0.5 rounded-full font-bold ${isFixedOk ? 'bg-green-600 text-white' : 'bg-red-600 text-white'}`}>
              {(fixedPercent * 100).toFixed(1)}%
            </span>
          </div>
          <p className="text-sm">
            {isFixedOk 
              ? "Parabéns! Suas contas fixas estão dentro do limite ideal de 55%." 
              : `Atenção! Suas contas fixas estão consumindo muito da sua renda. O ideal é reduzir para 55%.`}
          </p>
        </div>

        {/* Leisure Diagnosis */}
        <div className={`p-4 rounded-lg border ${isLeisureOk ? 'bg-green-100 border-green-200' : 'bg-yellow-100 border-yellow-200'}`}>
          <div className="flex justify-between items-center mb-2">
            <span className="font-semibold text-sm uppercase">Lazer / Pessoal</span>
            <span className={`text-xs px-2 py-0.5 rounded-full font-bold ${isLeisureOk ? 'bg-green-600 text-white' : 'bg-yellow-600 text-white'}`}>
              {(leisurePercent * 100).toFixed(1)}%
            </span>
          </div>
          <p className="text-sm">
            {isLeisureOk 
              ? "Seu gasto com lazer está equilibrado. Continue assim!" 
              : "Você está gastando um pouco além do recomendado (15%) com lazer este mês."}
          </p>
        </div>

        {/* Balance Diagnosis */}
        <div className={`p-4 rounded-lg border ${isBalanceOk ? 'bg-green-100 border-green-200' : 'bg-red-100 border-red-200'}`}>
          <div className="flex justify-between items-center mb-2">
            <span className="font-semibold text-sm uppercase">Saldo do Mês</span>
            <span className="font-bold">{formatCurrency(balance)}</span>
          </div>
          <p className="text-sm">
            {isBalanceOk 
              ? "Mês no azul! Você está conseguindo poupar para o seu futuro." 
              : "Cuidado! Suas despesas superaram sua renda este mês. Revise seus gastos."}
          </p>
        </div>
      </div>
    </div>
  );
};

export default Diagnosis;

import React, { useState, useEffect, useMemo } from 'react';
import { CategoryType, FinanceItem, SummaryData } from './types';
import { getNext12Months, formatCurrency } from './constants';
import BlockSection from './components/BlockSection';
import Diagnosis from './components/Diagnosis';

const App: React.FC = () => {
  const months = useMemo(() => getNext12Months(), []);

  // State for all financial items
  const [items, setItems] = useState<FinanceItem[]>(() => {
    const saved = localStorage.getItem('finance_data');
    return saved ? JSON.parse(saved) : [];
  });

  // Reminder settings
  const [reminderDays, setReminderDays] = useState<number>(3);
  const [showReminderConfig, setShowReminderConfig] = useState(false);

  // Persistence
  useEffect(() => {
    localStorage.setItem('finance_data', JSON.stringify(items));
  }, [items]);

  const handleAddItem = (category: CategoryType) => {
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '',
      category,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    };
    setItems([...items, newItem]);
  };

  const handleUpdateValue = (id: string, monthIdx: number, value: string) => {
    const numericValue = parseFloat(value) || 0;
    setItems(items.map(item => 
      item.id === id 
      ? { ...item, values: item.values.map((v, i) => i === monthIdx ? numericValue : v) }
      : item
    ));
  };

  const handleUpdateDescription = (id: string, desc: string) => {
    setItems(items.map(item => item.id === id ? { ...item, description: desc } : item));
  };

  const handleTogglePaid = (id: string, monthIdx: number) => {
    setItems(items.map(item => 
      item.id === id 
      ? { ...item, paidStatus: item.paidStatus.map((s, i) => i === monthIdx ? !s : s) }
      : item
    ));
  };

  const handleRemoveItem = (id: string) => {
    if (confirm('Deseja realmente excluir este item?')) {
      setItems(items.filter(item => item.id !== id));
    }
  };

  // Calculations for Summary
  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;

    for (let m = 0; m < 12; m++) {
      const totalIncome = items
        .filter(i => i.category === CategoryType.INCOME)
        .reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalCreditCard = items
        .filter(i => i.category === CategoryType.CREDIT_CARD)
        .reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalFixed = items
        .filter(i => i.category === CategoryType.FIXED_EXPENSE)
        .reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalVariable = items
        .filter(i => i.category === CategoryType.VARIABLE_EXPENSE)
        .reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalLeisure = items
        .filter(i => i.category === CategoryType.PERSONAL_LEISURE)
        .reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalCost = totalCreditCard + totalFixed + totalVariable + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;

      summaries.push({
        totalIncome,
        totalCreditCard,
        totalFixed,
        totalVariable,
        totalLeisure,
        totalCost,
        balance,
        accumulated
      });
    }
    return summaries;
  }, [items]);

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-gray-900 text-white p-6 shadow-lg mb-8 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-green-600 rounded-lg flex items-center justify-center">
              <i className="fas fa-wallet text-2xl"></i>
            </div>
            <div>
              <h1 className="text-2xl font-bold">Financeira 12 Meses</h1>
              <p className="text-gray-400 text-xs uppercase tracking-widest">Controle Simples e Eficaz</p>
            </div>
          </div>

          <div className="flex items-center gap-4 bg-gray-800 p-2 rounded-lg border border-gray-700">
            <div className="text-sm flex items-center gap-2">
              <i className="fas fa-bell text-yellow-500"></i>
              <span>Lembrete: {reminderDays} dias</span>
            </div>
            <button 
              onClick={() => setShowReminderConfig(!showReminderConfig)}
              className="text-xs bg-gray-700 hover:bg-gray-600 px-3 py-1 rounded transition-colors"
            >
              Configurar
            </button>
          </div>
        </div>

        {showReminderConfig && (
          <div className="max-w-7xl mx-auto mt-4 p-4 bg-gray-800 rounded-lg border border-gray-700 animate-fade-in">
            <p className="text-sm mb-2">A cada quantos dias você quer um lembrete para atualizar?</p>
            <div className="flex gap-2">
              {[2, 3, 5, 7].map(d => (
                <button
                  key={d}
                  onClick={() => { setReminderDays(d); setShowReminderConfig(false); }}
                  className={`px-4 py-2 rounded text-sm ${reminderDays === d ? 'bg-green-600' : 'bg-gray-700 hover:bg-gray-600'}`}
                >
                  {d} dias
                </button>
              ))}
            </div>
          </div>
        )}
      </header>

      {/* Main Content */}
      <main className="max-w-[1600px] mx-auto px-4 md:px-8">

        {/* Weekly Update Alert */}
        <div className="mb-8 bg-yellow-50 border-l-4 border-yellow-400 p-4 rounded-r-lg flex items-center justify-between">
          <div className="flex items-center gap-3">
            <i className="fas fa-exclamation-triangle text-yellow-600 text-xl"></i>
            <p className="text-yellow-800 font-medium">Lembre-se de atualizar sua planilha pelo menos uma vez por semana!</p>
          </div>
        </div>

        {/* Diagnosis for current month (first month) */}
        <Diagnosis summary={monthlySummaries[0]} monthName={months[0].monthName} />

        {/* Financial Blocks */}
        <BlockSection 
          title="ENTRADAS (Rendas)" 
          category={CategoryType.INCOME}
          items={items.filter(i => i.category === CategoryType.INCOME)}
          months={months}
          onAddItem={handleAddItem}
          onUpdateValue={handleUpdateValue}
          onTogglePaid={handleTogglePaid}
          onRemoveItem={handleRemoveItem}
          onUpdateDescription={handleUpdateDescription}
        />

        <BlockSection 
          title="FATURAS DE CARTÃO" 
          category={CategoryType.CREDIT_CARD}
          items={items.filter(i => i.category === CategoryType.CREDIT_CARD)}
          months={months}
          onAddItem={handleAddItem}
          onUpdateValue={handleUpdateValue}
          onTogglePaid={handleTogglePaid}
          onRemoveItem={handleRemoveItem}
          onUpdateDescription={handleUpdateDescription}
        />

        <BlockSection 
          title="CONTAS FIXAS" 
          category={CategoryType.FIXED_EXPENSE}
          items={items.filter(i => i.category === CategoryType.FIXED_EXPENSE)}
          months={months}
          onAddItem={handleAddItem}
          onUpdateValue={handleUpdateValue}
          onTogglePaid={handleTogglePaid}
          onRemoveItem={handleRemoveItem}
          onUpdateDescription={handleUpdateDescription}
        />

        <BlockSection 
          title="CONTAS VARIÁVEIS" 
          category={CategoryType.VARIABLE_EXPENSE}
          items={items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE)}
          months={months}
          onAddItem={handleAddItem}
          onUpdateValue={handleUpdateValue}
          onTogglePaid={handleTogglePaid}
          onRemoveItem={handleRemoveItem}
          onUpdateDescription={handleUpdateDescription}
        />

        <BlockSection 
          title="LAZER E GASTOS PESSOAIS" 
          category={CategoryType.PERSONAL_LEISURE}
          items={items.filter(i => i.category === CategoryType.PERSONAL_LEISURE)}
          months={months}
          onAddItem={handleAddItem}
          onUpdateValue={handleUpdateValue}
          onTogglePaid={handleTogglePaid}
          onRemoveItem={handleRemoveItem}
          onUpdateDescription={handleUpdateDescription}
        />

        {/* Summary Block */}
        <div className="bg-gray-900 rounded-xl shadow-2xl overflow-hidden mt-12 mb-20">
          <div className="bg-gray-800 p-4 border-b border-gray-700">
            <h3 className="text-white font-bold text-lg uppercase tracking-wider text-center">Resumo e Projeção Acumulada</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-gray-800 text-gray-400">
                  <th className="p-4 min-w-[200px]">DESCRIÇÃO</th>
                  {months.map((m, idx) => (
                    <th key={idx} className="p-4 text-center border-l border-gray-700">{m.monthName}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="text-white">
                <tr className="border-b border-gray-800">
                  <td className="p-4 font-semibold text-green-400">ENTRADAS TOTAIS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l border-gray-800">{formatCurrency(s.totalIncome)}</td>
                  ))}
                </tr>
                <tr className="border-b border-gray-800">
                  <td className="p-4 text-gray-300">CARTÕES DE CRÉDITO</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l border-gray-800">{formatCurrency(s.totalCreditCard)}</td>
                  ))}
                </tr>
                <tr className="border-b border-gray-800">
                  <td className="p-4 text-gray-300">CONTAS FIXAS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l border-gray-800">{formatCurrency(s.totalFixed)}</td>
                  ))}
                </tr>
                <tr className="border-b border-gray-800">
                  <td className="p-4 text-gray-300">CONTAS VARIÁVEIS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l border-gray-800">{formatCurrency(s.totalVariable)}</td>
                  ))}
                </tr>
                <tr className="border-b border-gray-800">
                  <td className="p-4 text-gray-300">LAZER / GASTOS PESSOAIS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l border-gray-800">{formatCurrency(s.totalLeisure)}</td>
                  ))}
                </tr>
                <tr className="border-b border-gray-700 bg-gray-800">
                  <td className="p-4 font-bold text-red-400">TOTAL DE CUSTOS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l border-gray-700 font-bold">{formatCurrency(s.totalCost)}</td>
                  ))}
                </tr>
                <tr className="border-b border-gray-700">
                  <td className="p-4 font-bold">SOBRA/FALTA NO MÊS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l border-gray-700 font-bold ${s.balance >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                      {formatCurrency(s.balance)}
                    </td>
                  ))}
                </tr>
                <tr className="bg-green-900/30">
                  <td className="p-4 font-black uppercase text-green-300">ACUMULATIVO</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l border-gray-700 font-black text-lg ${s.accumulated >= 0 ? 'text-green-300' : 'text-red-400'}`}>
                      {formatCurrency(s.accumulated)}
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </main>

      {/* Footer / Mobile Nav */}
      <footer className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-3 md:hidden flex justify-around">
        <button className="flex flex-col items-center text-blue-600">
          <i className="fas fa-table text-xl"></i>
          <span className="text-[10px] mt-1">Planilha</span>
        </button>
        <button className="flex flex-col items-center text-gray-400" onClick={() => window.scrollTo({top: 0, behavior: 'smooth'})}>
          <i className="fas fa-stethoscope text-xl"></i>
          <span className="text-[10px] mt-1">Análise</span>
        </button>
        <button className="flex flex-col items-center text-gray-400">
          <i className="fas fa-cog text-xl"></i>
          <span className="text-[10px] mt-1">Ajustes</span>
        </button>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { CategoryType, FinanceItem } from '../types';
import { formatCurrency } from '../constants';

interface BlockSectionProps {
  title: string;
  category: CategoryType;
  items: FinanceItem[];
  months: any[];
  onAddItem: (category: CategoryType) => void;
  onUpdateValue: (id: string, monthIdx: number, value: string) => void;
  onTogglePaid: (id: string, monthIdx: number) => void;
  onRemoveItem: (id: string) => void;
  onUpdateDescription: (id: string, desc: string) => void;
}

const BlockSection: React.FC<BlockSectionProps> = ({
  title,
  category,
  items,
  months,
  onAddItem,
  onUpdateValue,
  onTogglePaid,
  onRemoveItem,
  onUpdateDescription
}) => {
  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden mb-8">
      <div className="bg-gray-800 p-4 flex justify-between items-center">
        <h3 className="text-white font-bold text-lg uppercase tracking-wider">{title}</h3>
        <button 
          onClick={() => onAddItem(category)}
          className="bg-green-600 hover:bg-green-500 text-white px-3 py-1 rounded text-sm transition-colors flex items-center gap-2"
        >
          <i className="fas fa-plus"></i> Adicionar
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="bg-gray-100 text-gray-700 uppercase font-semibold">
