                            isPaid 
                              ? 'border-green-500 text-green-800 font-bold bg-green-50 shadow-inner' 
                              : 'border-gray-200'
                          }`}
                          placeholder="0,00"
                        />
                        {!isIncome && (
                          <button
                            onClick={() => onTogglePaid(item.id, mIdx)}
