                            className={`w-full text-[10px] px-2 py-1 rounded-md border font-bold transition-all shadow-sm flex items-center justify-center gap-1 ${
                              isPaid 
                                ? 'bg-green-600 text-white border-green-700 hover:bg-green-700' 
                                : 'bg-white text-gray-500 border-gray-300 hover:border-green-500 hover:text-green-600'
                            }`}
                          >
                            {isPaid ? (
                              <><i className="fas fa-check-circle"></i> PAGO</>
                            ) : (
                              'PAGAR'
                            )}
                          </button>
                        )}
                      </div>
                    </td>
                  );
                })}
                <td className="p-2 text-center">
                  <button 
                    onClick={() => onRemoveItem(item.id)}
                    className="text-gray-300 hover:text-red-500 transition-colors"
                  >
                    <i className="fas fa-trash-alt"></i>
                  </button>
                </td>
              </tr>
            ))}
            {items.length === 0 && (
              <tr>
                <td colSpan={months.length + 2} className="p-8 text-center text-gray-400 italic">
                  Nenhum item adicionado nesta categoria.
                </td>
              </tr>
            )}
          </tbody>
          <tfoot className="bg-gray-50 font-bold">
            <tr>
              <td className="p-3">SUBTOTAL</td>
              {months.map((_, mIdx) => {
                const total = items.reduce((acc, item) => acc + (item.values[mIdx] || 0), 0);
                return (
                  <td key={mIdx} className="p-3 text-center border-l text-blue-700">
                    {formatCurrency(total)}
                  </td>
                );
              })}
              <td></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

