import React, { useState, useEffect, useMemo } from 'react';
import { CategoryType, FinanceItem, SummaryData } from './types';
import { getNext12Months, formatCurrency } from './constants';
import BlockSection from './components/BlockSection';
import Diagnosis from './components/Diagnosis';

const App: React.FC = () => {
  const months = useMemo(() => getNext12Months(), []);
  const [items, setItems] = useState<FinanceItem[]>(() => {
    const saved = localStorage.getItem('finance_data');
    return saved ? JSON.parse(saved) : [];
  });
  const [reminderDays, setReminderDays] = useState<number>(3);
  const [showReminderConfig, setShowReminderConfig] = useState(false);

  useEffect(() => { localStorage.setItem('finance_data', JSON.stringify(items)); }, [items]);

  const handleAddItem = (category: CategoryType) => {
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '', category,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    };
    setItems([...items, newItem]);
  };

  const handleUpdateValue = (id: string, monthIdx: number, value: string) => {
    const numericValue = parseFloat(value) || 0;
    setItems(items.map(item => item.id === id ? { ...item, values: item.values.map((v, i) => i === monthIdx ? numericValue : v) } : item));
  };

  const handleUpdateDescription = (id: string, desc: string) => {
    setItems(items.map(item => item.id === id ? { ...item, description: desc } : item));
  };

  const handleTogglePaid = (id: string, monthIdx: number) => {
    setItems(items.map(item => item.id === id ? { ...item, paidStatus: item.paidStatus.map((s, i) => i === monthIdx ? !s : s) } : item));
  };

  const handleRemoveItem = (id: string) => { if (confirm('Excluir este item?')) setItems(items.filter(item => item.id !== id)); };

  const handleReplicateValue = (id: string, monthIdx: number) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    const valueToReplicate = item.values[monthIdx];
    setItems(items.map(i => i.id === id ? { ...i, values: i.values.map((v, idx) => idx >= monthIdx ? valueToReplicate : v) } : i));
  };

  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;
    for (let m = 0; m < 12; m++) {
      const totalIncome = items.filter(i => i.category === CategoryType.INCOME).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCreditCard = items.filter(i => i.category === CategoryType.CREDIT_CARD).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixed = items.filter(i => i.category === CategoryType.FIXED_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariable = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalLeisure = items.filter(i => i.category === CategoryType.PERSONAL_LEISURE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCost = totalCreditCard + totalFixed + totalVariable + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;
      summaries.push({ totalIncome, totalCreditCard, totalFixed, totalVariable, totalLeisure, totalCost, balance, accumulated });
    }
    return summaries;
  }, [items]);

  return (
    <div className="min-h-screen pb-20 bg-black text-gray-100">
      <header className="bg-zinc-900 text-white p-6 shadow-2xl mb-8 sticky top-0 z-50 border-b border-yellow-500/30">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-yellow-500 rounded-lg flex items-center justify-center shadow-[0_0_15px_rgba(234,179,8,0.4)]">
              <i className="fas fa-gem text-black text-2xl"></i>
            </div>
            <div>
              <h1 className="text-2xl font-black text-yellow-500 italic">RICO NESTA VIDA</h1>
              <p className="text-gray-400 text-[10px] uppercase tracking-[0.3em]">Master Financial Planning</p>
            </div>
          </div>
          <div className="flex items-center gap-4 bg-black p-2 rounded-lg border border-yellow-500/20">
            <div className="text-sm flex items-center gap-2">
              <i className="fas fa-bell text-yellow-500"></i>
              <span className="text-gray-300">Lembrete: {reminderDays} dias</span>
            </div>
            <button onClick={() => setShowReminderConfig(!showReminderConfig)} className="text-xs bg-yellow-500 hover:bg-yellow-400 text-black font-bold px-3 py-1 rounded transition-all">CONFIGURAR</button>
          </div>
        </div>
        {showReminderConfig && (
          <div className="max-w-7xl mx-auto mt-4 p-4 bg-zinc-800 rounded-lg border border-yellow-500/30 shadow-xl">
            <p className="text-sm mb-2 text-yellow-500 font-bold uppercase tracking-wider">Intervalo de atualização</p>
            <div className="flex gap-2">
              {[2, 3, 5, 7].map(d => (
                <button key={d} onClick={() => { setReminderDays(d); setShowReminderConfig(false); }} className={`px-4 py-2 rounded text-sm font-bold transition-all ${reminderDays === d ? 'bg-yellow-500 text-black' : 'bg-zinc-700 text-gray-300 hover:bg-zinc-600'}`}>
                  {d} dias
                </button>
              ))}
            </div>
          </div>
        )}
      </header>

      <main className="max-w-[1600px] mx-auto px-4 md:px-8">
        <div className="mb-8 bg-yellow-500/10 border-l-4 border-yellow-500 p-4 rounded-r-lg flex items-center justify-between shadow-lg">
          <div className="flex items-center gap-3">
            <i className="fas fa-calendar-check text-yellow-500 text-xl"></i>
            <p className="text-yellow-100 font-medium">Mantenha sua jornada ativa: atualize seus lançamentos semanalmente.</p>
          </div>
        </div>

        <Diagnosis summary={monthlySummaries[0]} monthName={months[0].monthName} />

        {[
          { title: "ENTRADAS (Rendas)", type: CategoryType.INCOME },
          { title: "FATURAS DE CARTÃO", type: CategoryType.CREDIT_CARD },
          { title: "CONTAS FIXAS", type: CategoryType.FIXED_EXPENSE },
          { title: "CONTAS VARIÁVEIS", type: CategoryType.VARIABLE_EXPENSE },
          { title: "LAZER E GASTOS PESSOAIS", type: CategoryType.PERSONAL_LEISURE }
        ].map(block => (
          <BlockSection key={block.type} title={block.title} category={block.type} items={items.filter(i => i.category === block.type)} months={months} onAddItem={handleAddItem} onUpdateValue={handleUpdateValue} onTogglePaid={handleTogglePaid} onRemoveItem={handleRemoveItem} onUpdateDescription={handleUpdateDescription} onReplicateValue={handleReplicateValue} />
        ))}

        <div className="bg-zinc-900 rounded-xl shadow-2xl overflow-hidden mt-12 mb-20 border border-yellow-500/20">
          <div className="bg-zinc-800 p-4 border-b border-yellow-500/30 text-center">
            <h3 className="text-yellow-500 font-black text-lg uppercase tracking-widest italic">Resumo Estratégico</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-zinc-950 text-gray-400">
                  <th className="p-4 min-w-[200px] uppercase font-bold text-xs tracking-tighter">Categoria</th>
                  {months.map((m, idx) => (
                    <th key={idx} className="p-4 text-center border-l border-zinc-800">{m.monthName}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="text-gray-100">
                <tr className="border-b border-zinc-800">
                  <td className="p-4 font-bold text-yellow-500">ENTRADAS TOTAIS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l border-zinc-800">{formatCurrency(s.totalIncome)}</td>
                  ))}
                </tr>
                {['CARTÕES DE CRÉDITO', 'CONTAS FIXAS', 'CONTAS VARIÁVEIS', 'LAZER / GASTOS PESSOAIS'].map((cat, i) => (
                   <tr key={cat} className="border-b border-zinc-800 text-gray-400">
                    <td className="p-4">{cat}</td>
                    {monthlySummaries.map((s, idx) => {
                      const vals = [s.totalCreditCard, s.totalFixed, s.totalVariable, s.totalLeisure];
                      return <td key={idx} className="p-4 text-center border-l border-zinc-800">{formatCurrency(vals[i])}</td>
                    })}
                   </tr>
                ))}
                <tr className="border-b border-zinc-700 bg-zinc-950">
                  <td className="p-4 font-bold text-gray-300">TOTAL DE CUSTOS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l border-zinc-700 font-bold">{formatCurrency(s.totalCost)}</td>
                  ))}
                </tr>
                <tr className="border-b border-zinc-700">
                  <td className="p-4 font-bold uppercase text-xs">SOBRA/FALTA NO MÊS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l border-zinc-700 font-bold ${s.balance >= 0 ? 'text-yellow-500' : 'text-red-400'}`}>
                      {formatCurrency(s.balance)}
                    </td>
                  ))}
                </tr>
                <tr className="bg-yellow-500/10">
                  <td className="p-4 font-black uppercase text-yellow-500 text-sm italic">ACUMULATIVO</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l border-zinc-700 font-black text-lg ${s.accumulated >= 0 ? 'text-yellow-500' : 'text-red-400'}`}>
                      {formatCurrency(s.accumulated)}
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

