    const item = items.find(i => i.id === id);
    if (!item) return;
    const valueToReplicate = item.values[monthIdx];
    setItems(items.map(i => i.id === id ? { ...i, values: i.values.map((v, idx) => idx >= monthIdx ? valueToReplicate : v) } : i));
  };

  const handleLinkCard = (itemId: string, cardId: string) => {
    setItems(items.map(item => item.id === itemId ? { ...item, linkedCardId: cardId || undefined } : item));
  };

  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;
    for (let m = 0; m < 12; m++) {
      const totalIncome = items.filter(i => i.category === CategoryType.INCOME).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      // Faturas brutas informadas pelo usuário
      const totalCreditCardBruto = items.filter(i => i.category === CategoryType.CREDIT_CARD).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      // Contas Fixas: Somamos apenas as que NÃO estão vinculadas a cartões para o total de custo
      // mas mantemos a visualização total no bloco específico.
      const totalFixed = items.filter(i => i.category === CategoryType.FIXED_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixedDuplicado = items.filter(i => i.category === CategoryType.FIXED_EXPENSE && i.linkedCardId).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalVariable = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariableDuplicado = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE && i.linkedCardId).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalLeisure = items.filter(i => i.category === CategoryType.PERSONAL_LEISURE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      // Cálculo de Custo Real: Fatura do Cartão + (Fixas - Fixas no Cartão) + (Variáveis - Variáveis no Cartão) + Lazer
      // Isso assume que o valor digitado na "Fatura do Cartão" já contém esses itens.
      const realFixed = totalFixed - totalFixedDuplicado;
      const realVariable = totalVariable - totalVariableDuplicado;

      const totalCost = totalCreditCardBruto + realFixed + realVariable + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;

      summaries.push({ 
        totalIncome, 
        totalCreditCard: totalCreditCardBruto, 
        totalFixed: totalFixed, // Mantemos o valor visual total para o resumo
        totalVariable: totalVariable, 
        totalLeisure, 
        totalCost, 
        balance, 
        accumulated 
      });
    }
    return summaries;
  }, [items]);

  const allCards = useMemo(() => items.filter(i => i.category === CategoryType.CREDIT_CARD), [items]);

  return (
    <div className="min-h-screen pb-20 bg-gray-50 text-gray-900">
      <header className="bg-zinc-900 text-white p-6 shadow-2xl mb-8 sticky top-0 z-50 border-b border-yellow-500/30">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-yellow-500 rounded-lg flex items-center justify-center shadow-[0_0_15px_rgba(234,179,8,0.4)]">
              <i className="fas fa-gem text-black text-2xl"></i>
            </div>
            <div>
              <h1 className="text-2xl font-black text-yellow-500 italic uppercase">RICO NESTA VIDA</h1>
              <p className="text-gray-400 text-[10px] uppercase tracking-[0.3em]">Master Financial Planning</p>
            </div>
          </div>
          <div className="flex items-center gap-4 bg-black p-2 rounded-lg border border-yellow-500/20">
            <div className="text-sm flex items-center gap-2">
              <i className="fas fa-bell text-yellow-500"></i>
              <span className="text-gray-300">Lembrete: {reminderDays} dias</span>
            </div>
            <button onClick={() => setShowReminderConfig(!showReminderConfig)} className="text-xs bg-yellow-500 hover:bg-yellow-400 text-black font-bold px-3 py-1 rounded transition-all">CONFIGURAR</button>
          </div>
        </div>
        {showReminderConfig && (
          <div className="max-w-7xl mx-auto mt-4 p-4 bg-zinc-800 rounded-lg border border-yellow-500/30 shadow-xl">
            <p className="text-sm mb-2 text-yellow-500 font-bold uppercase tracking-wider text-center">Intervalo de atualização</p>
            <div className="flex gap-2 justify-center">
              {[2, 3, 5, 7].map(d => (
                <button key={d} onClick={() => { setReminderDays(d); setShowReminderConfig(false); }} className={`px-4 py-2 rounded text-sm font-bold transition-all ${reminderDays === d ? 'bg-yellow-500 text-black' : 'bg-zinc-700 text-gray-300 hover:bg-zinc-600'}`}>
                  {d} dias
                </button>
              ))}
            </div>
          </div>
        )}
      </header>

      <main className="max-w-[1600px] mx-auto px-4 md:px-8">
        <div className="mb-8 bg-zinc-900 border-l-4 border-yellow-500 p-4 rounded-r-lg flex items-center justify-between shadow-lg">
          <div className="flex items-center gap-3">
            <i className="fas fa-calendar-check text-yellow-500 text-xl"></i>
            <p className="text-gray-100 font-medium">Mantenha sua jornada ativa: atualize seus lançamentos semanalmente.</p>
          </div>
        </div>

        <Diagnosis summary={monthlySummaries[0]} monthName={months[0].monthName} />

        {[
          { title: "ENTRADAS (Rendas)", type: CategoryType.INCOME },
          { title: "FATURAS DE CARTÃO", type: CategoryType.CREDIT_CARD },
          { title: "CONTAS FIXAS", type: CategoryType.FIXED_EXPENSE },
          { title: "CONTAS VARIÁVEIS", type: CategoryType.VARIABLE_EXPENSE },
          { title: "LAZER E GASTOS PESSOAIS", type: CategoryType.PERSONAL_LEISURE }
        ].map(block => (
          <BlockSection 
            key={block.type} 
            title={block.title} 
            category={block.type} 
            items={items.filter(i => i.category === block.type)} 
            allCards={allCards}
            months={months} 
            onAddItem={handleAddItem} 
            onUpdateValue={handleUpdateValue} 
            onTogglePaid={handleTogglePaid} 
            onRemoveItem={handleRemoveItem} 
            onUpdateDescription={handleUpdateDescription} 
            onReplicateValue={handleReplicateValue}
            onLinkCard={handleLinkCard}
          />
        ))}

        <div className="bg-white rounded-xl shadow-sm overflow-hidden mt-12 mb-20 border border-gray-200">
          <div className="bg-zinc-900 p-4 border-b border-yellow-500/30 text-center">
            <h3 className="text-yellow-500 font-black text-lg uppercase tracking-widest italic">Resumo Estratégico</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-gray-50 text-gray-500">
                  <th className="p-4 min-w-[200px] uppercase font-bold text-xs tracking-tighter">Categoria</th>
                  {months.map((m, idx) => (
                    <th key={idx} className="p-4 text-center border-l border-gray-100">{m.monthName}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="text-gray-900">
                <tr className="border-b">
                  <td className="p-4 font-bold text-green-600 bg-green-50">ENTRADAS TOTAIS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l bg-green-50">{formatCurrency(s.totalIncome)}</td>
                  ))}
                </tr>
                {['CARTÕES DE CRÉDITO', 'CONTAS FIXAS', 'CONTAS VARIÁVEIS', 'LAZER / GASTOS PESSOAIS'].map((cat, i) => (
                   <tr key={cat} className="border-b text-gray-600">
                    <td className="p-4">{cat}</td>
                    {monthlySummaries.map((s, idx) => {
                      const vals = [s.totalCreditCard, s.totalFixed, s.totalVariable, s.totalLeisure];
                      return <td key={idx} className="p-4 text-center border-l">{formatCurrency(vals[i])}</td>
                    })}
                   </tr>
                ))}
                <tr className="border-b bg-gray-50">
                  <td className="p-4 font-bold text-gray-700">TOTAL DE CUSTOS (SEM DUPLICIDADE)</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l font-bold">{formatCurrency(s.totalCost)}</td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="p-4 font-bold uppercase text-xs">SOBRA/FALTA NO MÊS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l font-bold ${s.balance >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                      {formatCurrency(s.balance)}
                    </td>
                  ))}
                </tr>
                <tr className="bg-zinc-900 text-white">
                  <td className="p-4 font-black uppercase text-yellow-500 text-sm italic">ACUMULATIVO</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l border-zinc-800 font-black text-lg ${s.accumulated >= 0 ? 'text-yellow-500' : 'text-red-400'}`}>
                      {formatCurrency(s.accumulated)}
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
          <div className="p-4 bg-gray-100 text-[10px] text-gray-500 italic">
            * Contas sinalizadas como pagas via cartão são deduzidas do total de Contas Fixas/Variáveis no cálculo do Custo Real para evitar duplicidade, assumindo que já compõem o valor da fatura.
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

export enum CategoryType {
  INCOME = 'Renda',
  CREDIT_CARD = 'Cartão de Crédito',
  FIXED_EXPENSE = 'Contas Fixas',
  VARIABLE_EXPENSE = 'Contas Variáveis',
  PERSONAL_LEISURE = 'Lazer e Gastos Pessoais'
}

export enum LinkType {
  RECURRING = 'Recorrente', // Só abate no mês atual
  INSTALLMENT = 'Parcelado'  // Abate em todos os meses futuros
}

export interface MonthData {
  monthName: string;
  year: number;
}

export interface FinanceItem {
  id: string;
  description: string;
  category: CategoryType;
  values: number[]; // 12 months
  paidStatus: boolean[]; // 12 months
  linkedCardId?: string; 
  linkType?: LinkType;
}

export interface SummaryData {
  totalIncome: number;
  totalCreditCard: number;
  totalFixed: number;
  totalVariable: number;
  totalLeisure: number;
  totalCost: number;
  balance: number;
  accumulated: number;
}

import React from 'react';
import { CategoryType, FinanceItem, LinkType } from '../types';
import { formatCurrency } from '../constants';

interface BlockSectionProps {
  title: string;
  category: CategoryType;
  items: FinanceItem[];
  allCards?: FinanceItem[];
  months: any[];
  onAddItem: (category: CategoryType) => void;
  onUpdateValue: (id: string, monthIdx: number, value: string) => void;
  onTogglePaid: (id: string, monthIdx: number) => void;
  onRemoveItem: (id: string) => void;
  onUpdateDescription: (id: string, desc: string) => void;
  onReplicateValue: (id: string, monthIdx: number) => void;
  onLinkCard?: (itemId: string, cardId: string, linkType?: LinkType) => void;
}

const BlockSection: React.FC<BlockSectionProps> = ({
  title,
  category,
  items,
  allCards = [],
  months,
  onAddItem,
  onUpdateValue,
  onTogglePaid,
  onRemoveItem,
  onUpdateDescription,
  onReplicateValue,
  onLinkCard
}) => {
  const showLinkOption = category === CategoryType.FIXED_EXPENSE || category === CategoryType.VARIABLE_EXPENSE;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden mb-8">
      <div className="bg-zinc-900 p-4 flex justify-between items-center border-b border-yellow-500/20">
        <h3 className="text-yellow-500 font-black text-lg uppercase tracking-widest italic">{title}</h3>
        <button 
          onClick={() => onAddItem(category)}
          className="bg-yellow-500 hover:bg-yellow-400 text-black font-bold px-4 py-1.5 rounded-md transition-all shadow-lg flex items-center gap-2 text-sm"
        >
          <i className="fas fa-plus"></i> ADICIONAR
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="bg-gray-100 text-gray-700 uppercase font-semibold">
            <tr>
              <th className="p-4 border-b min-w-[200px]">Descrição</th>
              {months.map((m, idx) => (
                <th key={idx} className="p-4 border-b text-center min-w-[140px] border-l">
                  {m.monthName}
                </th>
              ))}
              <th className="p-4 border-b w-12"></th>
            </tr>
          </thead>
          <tbody>
            {items.map((item) => (
              <tr key={item.id} className="border-b hover:bg-gray-50 transition-colors">
                <td className="p-2">
                  <div className="flex flex-col gap-1">
                    <input
                      type="text"
                      value={item.description}
                      onChange={(e) => onUpdateDescription(item.id, e.target.value)}
                      className="w-full bg-transparent border-b border-transparent focus:border-yellow-500 outline-none p-2 text-gray-900 font-medium"
                      placeholder="Nome do item..."
                    />
                    {showLinkOption && onLinkCard && (
                      <div className="px-2 pb-1 flex flex-col gap-1">
                        <div className="flex items-center gap-2">
                          <i className="fas fa-credit-card text-[10px] text-gray-400"></i>
                          <select 
                            className="text-[10px] bg-transparent border-none text-gray-500 focus:ring-0 cursor-pointer hover:text-yellow-600 transition-colors p-0"
                            value={item.linkedCardId || ''}
                            onChange={(e) => onLinkCard(item.id, e.target.value, item.linkType || LinkType.RECURRING)}
                          >
                            <option value="">Pagar via Dinheiro/Débito</option>
                            {allCards.map(card => (
                              <option key={card.id} value={card.id}>No cartão: {card.description || 'Sem nome'}</option>
                            ))}
                          </select>
                        </div>
                        {item.linkedCardId && (
                          <div className="flex items-center gap-2 ml-4">
                            <span className="text-[9px] text-gray-400 uppercase font-bold">Tipo:</span>
                            <select 
                              className="text-[9px] bg-zinc-100 rounded px-1 text-zinc-600 font-bold border-none focus:ring-0 cursor-pointer"
                              value={item.linkType || LinkType.RECURRING}
                              onChange={(e) => onLinkCard(item.id, item.linkedCardId!, e.target.value as LinkType)}
                            >
                              <option value={LinkType.RECURRING}>Recorrente (Mês a mês)</option>
                              <option value={LinkType.INSTALLMENT}>Parcelado (Já na fatura)</option>
                            </select>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </td>
                {item.values.map((val, mIdx) => {
                  const isPaid = item.paidStatus[mIdx];
                  const isIncome = category === CategoryType.INCOME;

                  return (
                    <td key={mIdx} className={`p-2 border-l text-center transition-all ${isPaid ? 'bg-green-50' : ''}`}>
                      <div className="flex flex-col gap-2 items-center">
                        <div className="relative w-full group">
                          <input
                            type="number"
                            value={val || ''}
                            onChange={(e) => onUpdateValue(item.id, mIdx, e.target.value)}
                            className={`w-full text-center bg-white border rounded p-2 focus:ring-2 focus:ring-yellow-500 outline-none transition-all ${
                              isPaid 
                                ? 'border-green-500 text-green-700 font-bold' 
                                : 'border-gray-200 text-gray-900'
                            }`}
                            placeholder="0,00"
                          />
                          <button
                            onClick={() => onReplicateValue(item.id, mIdx)}
                            title="Replicar este valor para os meses seguintes"
                            className="absolute -right-1 -top-1 opacity-0 group-hover:opacity-100 bg-yellow-500 text-black w-5 h-5 rounded-full flex items-center justify-center text-[10px] shadow-lg transition-opacity hover:scale-110"
                          >
                            <i className="fas fa-sync-alt"></i>
                          </button>
                        </div>
                        {!isIncome && (
                          <button
                            onClick={() => onTogglePaid(item.id, mIdx)}
                            className={`w-full text-[9px] py-1 rounded border font-black transition-all shadow-sm ${
                              isPaid 
                                ? 'bg-green-600 text-white border-green-600' 
                                : 'bg-white text-gray-400 border-gray-300 hover:border-green-500 hover:text-green-600'
                            }`}
                          >
                            {isPaid ? <><i className="fas fa-check mr-1"></i> PAGO</> : 'PENDENTE'}
                          </button>
                        )}
                      </div>
                    </td>
                  );
                })}
                <td className="p-2 text-center">
                  <button 
                    onClick={() => onRemoveItem(item.id)}
                    className="text-gray-300 hover:text-red-500 transition-colors"
                  >
                    <i className="fas fa-trash-alt"></i>
                  </button>
                </td>
              </tr>
            ))}
            {items.length === 0 && (
              <tr>
                <td colSpan={months.length + 2} className="p-8 text-center text-gray-400 italic">
                  Nenhum item adicionado nesta categoria.
                </td>
              </tr>
            )}
          </tbody>
          <tfoot className="bg-gray-50 font-bold">
            <tr>
              <td className="p-4 text-gray-600">SUBTOTAL</td>
              {months.map((_, mIdx) => {
                const total = items.reduce((acc, item) => acc + (item.values[mIdx] || 0), 0);
                return (
                  <td key={mIdx} className="p-4 text-center border-l text-zinc-900">
                    {formatCurrency(total)}
                  </td>
                );
              })}
              <td></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

export default BlockSection;

import React, { useState, useEffect, useMemo } from 'react';
import { CategoryType, FinanceItem, SummaryData, LinkType } from './types';
import { getNext12Months, formatCurrency } from './constants';
import BlockSection from './components/BlockSection';
import Diagnosis from './components/Diagnosis';

const App: React.FC = () => {
  const months = useMemo(() => getNext12Months(), []);
  const [items, setItems] = useState<FinanceItem[]>(() => {
    const saved = localStorage.getItem('finance_data');
    return saved ? JSON.parse(saved) : [];
  });
  const [reminderDays, setReminderDays] = useState<number>(3);
  const [showReminderConfig, setShowReminderConfig] = useState(false);

  useEffect(() => { localStorage.setItem('finance_data', JSON.stringify(items)); }, [items]);

  const handleAddItem = (category: CategoryType) => {
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '', category,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    };
    setItems([...items, newItem]);
  };

  const handleUpdateValue = (id: string, monthIdx: number, value: string) => {
    const numericValue = parseFloat(value) || 0;
    setItems(items.map(item => item.id === id ? { ...item, values: item.values.map((v, i) => i === monthIdx ? numericValue : v) } : item));
  };

  const handleUpdateDescription = (id: string, desc: string) => {
    setItems(items.map(item => item.id === id ? { ...item, description: desc } : item));
  };

  const handleTogglePaid = (id: string, monthIdx: number) => {
    setItems(items.map(item => item.id === id ? { ...item, paidStatus: item.paidStatus.map((s, i) => i === monthIdx ? !s : s) } : item));
  };

  const handleRemoveItem = (id: string) => { if (confirm('Excluir este item?')) setItems(items.filter(item => item.id !== id)); };

  const handleReplicateValue = (id: string, monthIdx: number) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    const valueToReplicate = item.values[monthIdx];
    setItems(items.map(i => i.id === id ? { ...i, values: i.values.map((v, idx) => idx >= monthIdx ? valueToReplicate : v) } : i));
  };

  const handleLinkCard = (itemId: string, cardId: string, linkType?: LinkType) => {
    setItems(items.map(item => item.id === itemId ? { 
      ...item, 
      linkedCardId: cardId || undefined,
      linkType: cardId ? (linkType || LinkType.RECURRING) : undefined 
    } : item));
  };

  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;
    for (let m = 0; m < 12; m++) {
      const totalIncome = items.filter(i => i.category === CategoryType.INCOME).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCreditCardBruto = items.filter(i => i.category === CategoryType.CREDIT_CARD).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalFixed = items.filter(i => i.category === CategoryType.FIXED_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      // Lógica de Abatimento:
      // Se m == 0 (mês atual), abatemos qualquer item vinculado ao cartão (Recorrente ou Parcelado)
      // Se m > 0 (futuro), abatemos APENAS se o vínculo for LinkType.INSTALLMENT (Parcelado)
      const totalFixedDuplicado = items.filter(i => {
        if (i.category !== CategoryType.FIXED_EXPENSE || !i.linkedCardId) return false;
        if (m === 0) return true; // Abate tudo no primeiro mês
        return i.linkType === LinkType.INSTALLMENT; // No futuro, só abate se for parcelado
      }).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalVariable = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariableDuplicado = items.filter(i => {
        if (i.category !== CategoryType.VARIABLE_EXPENSE || !i.linkedCardId) return false;
        if (m === 0) return true;
        return i.linkType === LinkType.INSTALLMENT;
      }).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalLeisure = items.filter(i => i.category === CategoryType.PERSONAL_LEISURE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const realFixed = totalFixed - totalFixedDuplicado;
      const realVariable = totalVariable - totalVariableDuplicado;

      const totalCost = totalCreditCardBruto + realFixed + realVariable + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;

      summaries.push({ 
        totalIncome, 
        totalCreditCard: totalCreditCardBruto, 
        totalFixed, 
        totalVariable, 
        totalLeisure, 
        totalCost, 
        balance, 
        accumulated 
      });
    }
    return summaries;
  }, [items]);

  const allCards = useMemo(() => items.filter(i => i.category === CategoryType.CREDIT_CARD), [items]);

  return (
    <div className="min-h-screen pb-20 bg-gray-50 text-gray-900">
      <header className="bg-zinc-900 text-white p-6 shadow-2xl mb-8 sticky top-0 z-50 border-b border-yellow-500/30">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-yellow-500 rounded-lg flex items-center justify-center shadow-[0_0_15px_rgba(234,179,8,0.4)]">
              <i className="fas fa-gem text-black text-2xl"></i>
            </div>
            <div>
              <h1 className="text-2xl font-black text-yellow-500 italic uppercase">RICO NESTA VIDA</h1>
              <p className="text-gray-400 text-[10px] uppercase tracking-[0.3em]">Master Financial Planning</p>
            </div>
          </div>
          <div className="flex items-center gap-4 bg-black p-2 rounded-lg border border-yellow-500/20">
            <div className="text-sm flex items-center gap-2">
              <i className="fas fa-bell text-yellow-500"></i>
              <span className="text-gray-300">Lembrete: {reminderDays} dias</span>
            </div>
            <button onClick={() => setShowReminderConfig(!showReminderConfig)} className="text-xs bg-yellow-500 hover:bg-yellow-400 text-black font-bold px-3 py-1 rounded transition-all">CONFIGURAR</button>
          </div>
        </div>
