                              className="text-[9px] bg-zinc-100 rounded px-1 text-zinc-600 font-bold border-none focus:ring-0 cursor-pointer"
                              value={item.linkType || LinkType.RECURRING}
                              onChange={(e) => onLinkCard(item.id, item.linkedCardId!, e.target.value as LinkType)}
                            >
                              <option value={LinkType.RECURRING}>Mês a mês</option>
                              <option value={LinkType.INSTALLMENT}>Já na fatura</option>
                            </select>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </td>
                {item.values.map((val, mIdx) => {
                  const isPaid = item.paidStatus[mIdx];
                  const isIncome = category === CategoryType.INCOME;

                  return (
                    <td key={mIdx} className={`p-2 border-l text-center transition-all ${isPaid ? 'bg-green-50/30' : ''}`}>
                      <div className="flex flex-col gap-1.5 items-center">
                        <div className="relative w-full group">
                          <input
                            type="number"
                            step="0.01"
                            value={val === 0 ? '' : val}
                            onChange={(e) => onUpdateValue(item.id, mIdx, e.target.value)}
