import React, { useState, useEffect, useMemo } from 'react';
import { CategoryType, FinanceItem, SummaryData, LinkType } from './types';
import { getNext12Months, formatCurrency, MONTHS_BR } from './constants';
import BlockSection from './components/BlockSection';
import Diagnosis from './components/Diagnosis';

const DEFAULT_FIXED_EXPENSES = [
  'Moradia', 'Condominio', 'Telefone fixo', 'Internet', 'Celular',
  'Compras mercado (média mensal)', 'Gás', 'Luz', 'Água', 'Convênio',
  'Gasolina/uber (media mensal)', 'Iptu (mensal)', 'Educação',
  'Unha e sobrancelha', 'Academia', 'Cabelo', 'Estética', 'Dízimo',
  'Diarista', 'Comida pet', 'Banho pet', 'Personal', 'Netflix', 'Spotify',
  'Emprestimo (parcela mensal)', 'Previdência', 'Parcela seguro carro',
  'Parcela de carro', 'Terapia', 'Emprestimo'
];

const App: React.FC = () => {
  const [startMonth, setStartMonth] = useState<number>(() => {
    const saved = localStorage.getItem('finance_start_month');
    return saved ? parseInt(saved) : new Date().getMonth();
  });

  const months = useMemo(() => getNext12Months(startMonth), [startMonth]);

  const [items, setItems] = useState<FinanceItem[]>(() => {
    const saved = localStorage.getItem('finance_data');
    if (saved) return JSON.parse(saved);

    return DEFAULT_FIXED_EXPENSES.map((desc, idx) => ({
      id: `default-fixed-${idx}`,
      description: desc,
      category: CategoryType.FIXED_EXPENSE,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    }));
  });

  const [reminderDays, setReminderDays] = useState<number>(3);
  const [showReminderConfig, setShowReminderConfig] = useState(false);

  const [showIncomeInstructions, setShowIncomeInstructions] = useState(false);
  const [showCardInstructions, setShowCardInstructions] = useState(false);
  const [showLeisureSuggestion, setShowLeisureSuggestion] = useState(false);

  const [dontShowIncomeInstructionsAgain, setDontShowIncomeInstructionsAgain] = useState(() => {
    return localStorage.getItem('hide_income_instructions') === 'true';
  });
  const [dontShowCardInstructionsAgain, setDontShowCardInstructionsAgain] = useState(() => {
    return localStorage.getItem('hide_card_instructions') === 'true';
  });
  const [dontShowLeisureSuggestionAgain, setDontShowLeisureSuggestionAgain] = useState(() => {
    return localStorage.getItem('hide_leisure_suggestion') === 'true';
  });

  useEffect(() => { 
    localStorage.setItem('finance_data', JSON.stringify(items)); 
  }, [items]);

  useEffect(() => {
    localStorage.setItem('finance_start_month', startMonth.toString());
  }, [startMonth]);

  const averageIncome = useMemo(() => {
    const incomeItems = items.filter(i => i.category === CategoryType.INCOME);
    if (incomeItems.length === 0) return 0;
    const total = incomeItems.reduce((acc, item) => acc + item.values[0], 0);
    return total;
  }, [items]);

  const handleAddItem = (category: CategoryType) => {
    if (category === CategoryType.INCOME && !dontShowIncomeInstructionsAgain) {
      setShowIncomeInstructions(true);
      return;
    }
    if (category === CategoryType.CREDIT_CARD && !dontShowCardInstructionsAgain) {
      setShowCardInstructions(true);
      return;
    }
    if (category === CategoryType.PERSONAL_LEISURE && !dontShowLeisureSuggestionAgain) {
      setShowLeisureSuggestion(true);
      return;
    }
    executeAddItem(category);
  };

  const executeAddItem = (category: CategoryType) => {
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: category === CategoryType.PERSONAL_LEISURE ? 'Lazer e Gastos Pessoais' : '', 
      category,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    };
    setItems([...items, newItem]);
    setShowIncomeInstructions(false);
    setShowCardInstructions(false);
    setShowLeisureSuggestion(false);
  };

  const handleToggleHideInstructions = (type: 'income' | 'card' | 'leisure') => {
    if (type === 'income') {
      const newValue = !dontShowIncomeInstructionsAgain;
      setDontShowIncomeInstructionsAgain(newValue);
      localStorage.setItem('hide_income_instructions', newValue.toString());
    } else if (type === 'card') {
      const newValue = !dontShowCardInstructionsAgain;
      setDontShowCardInstructionsAgain(newValue);
      localStorage.setItem('hide_card_instructions', newValue.toString());
    } else {
      const newValue = !dontShowLeisureSuggestionAgain;
      setDontShowLeisureSuggestionAgain(newValue);
      localStorage.setItem('hide_leisure_suggestion', newValue.toString());
    }
  };

  const handleUpdateValue = (id: string, monthIdx: number, value: string) => {
    const numericValue = value === '' ? 0 : parseFloat(value);
    setItems(items.map(item => item.id === id ? { ...item, values: item.values.map((v, i) => i === monthIdx ? numericValue : v) } : item));
  };

  const handleUpdateDescription = (id: string, desc: string) => {
    setItems(items.map(item => item.id === id ? { ...item, description: desc } : item));
  };

  const handleTogglePaid = (id: string, monthIdx: number) => {
    setItems(items.map(item => item.id === id ? { ...item, paidStatus: item.paidStatus.map((s, i) => i === monthIdx ? !s : s) } : item));
  };

  const handleRemoveItem = (id: string) => { if (confirm('Excluir este item?')) setItems(items.filter(item => item.id !== id)); };

  const handleReplicateValue = (id: string, monthIdx: number) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    const valueToReplicate = item.values[monthIdx];
    setItems(items.map(i => i.id === id ? { ...i, values: i.values.map((v, idx) => idx >= monthIdx ? valueToReplicate : v) } : i));
  };

  const handleLinkCard = (itemId: string, cardId: string, linkType?: LinkType) => {
    setItems(items.map(item => item.id === itemId ? { 
      ...item, 
      linkedCardId: cardId || undefined,
      linkType: cardId ? (linkType || LinkType.RECURRING) : undefined 
    } : item));
  };

  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;
    for (let m = 0; m < 12; m++) {
      const totalIncome = items.filter(i => i.category === CategoryType.INCOME).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCreditCardBruto = items.filter(i => i.category === CategoryType.CREDIT_CARD).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixed = items.filter(i => i.category === CategoryType.FIXED_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalFixedDuplicado = items.filter(i => {
        if (i.category !== CategoryType.FIXED_EXPENSE || !i.linkedCardId) return false;
        if (m === 0) return true;
        return i.linkType === LinkType.INSTALLMENT;
      }).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalVariable = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariableDuplicado = items.filter(i => {
        if (i.category !== CategoryType.VARIABLE_EXPENSE || !i.linkedCardId) return false;
        if (m === 0) return true;
        return i.linkType === LinkType.INSTALLMENT;
      }).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalLeisure = items.filter(i => i.category === CategoryType.PERSONAL_LEISURE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const realFixed = totalFixed - totalFixedDuplicado;
      const realVariable = totalVariable - totalVariableDuplicado;

      const totalCost = totalCreditCardBruto + realFixed + realVariable + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;

      summaries.push({ totalIncome, totalCreditCard: totalCreditCardBruto, totalFixed, totalVariable, totalLeisure, totalCost, balance, accumulated });
    }
    return summaries;
  }, [items]);

  const allCards = useMemo(() => items.filter(i => i.category === CategoryType.CREDIT_CARD), [items]);

  return (
    <div className="min-h-screen pb-20 bg-gray-50 text-gray-900">
      <header className="bg-[#0f0f0f] text-white p-8 shadow-2xl mb-8 sticky top-0 z-50 border-b-2 border-yellow-600/50">
        <div className="max-w-7xl mx-auto flex flex-col items-center gap-6 text-center">
          <div className="relative group">
            <div className="flex flex-col items-center">
              <div className="flex items-center gap-2">
                <span className="text-5xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-yellow-200 via-yellow-500 to-yellow-700 uppercase italic">RICO</span>
                <div className="w-14 h-14 border-2 border-yellow-500 rounded-full flex items-center justify-center relative shadow-[0_0_15px_rgba(234,179,8,0.3)]">
                  <i className="fas fa-sack-dollar text-yellow-500 text-3xl"></i>
                </div>
              </div>
              <div className="mt-[-8px]">
                <span className="text-2xl font-light tracking-[0.2em] text-gray-100 ml-4 lowercase">nessa vida</span>
              </div>
            </div>
          </div>

          <p className="text-yellow-500/80 text-xs md:text-sm uppercase tracking-[0.25em] font-medium max-w-lg">
            Uma vida financeiramente saudável é uma questão de escolha
          </p>

          <div className="absolute right-8 top-8 hidden lg:flex items-center gap-4 bg-zinc-900 p-2 rounded-lg border border-yellow-500/20">
            <div className="text-xs flex items-center gap-2">
              <i className="fas fa-bell text-yellow-500"></i>
              <span className="text-gray-400">Lembrete: {reminderDays} dias</span>
            </div>
            <button onClick={() => setShowReminderConfig(!showReminderConfig)} className="text-[10px] bg-yellow-600 hover:bg-yellow-500 text-black font-bold px-3 py-1 rounded transition-all">CONFIGURAR</button>
          </div>
        </div>

        {showReminderConfig && (
          <div className="max-w-md mx-auto mt-6 p-4 bg-zinc-800 rounded-lg border border-yellow-500/30 shadow-xl">
            <p className="text-xs mb-3 text-yellow-500 font-bold uppercase tracking-widest text-center">Intervalo de atualização</p>
            <div className="flex gap-2 justify-center">
              {[2, 3, 5, 7].map(d => (
                <button key={d} onClick={() => { setReminderDays(d); setShowReminderConfig(false); }} className={`px-4 py-2 rounded text-xs font-bold transition-all ${reminderDays === d ? 'bg-yellow-600 text-black' : 'bg-zinc-700 text-gray-300 hover:bg-zinc-600'}`}>
                  {d} dias
                </button>
              ))}
            </div>
          </div>
        )}
      </header>

      {/* Pop-up de Instruções para Entradas */}
      {showIncomeInstructions && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden border border-yellow-500/30 animate-in zoom-in duration-300">
            <div className="bg-zinc-900 p-6 flex items-center gap-4 border-b border-yellow-600/30">
              <div className="w-12 h-12 bg-yellow-500 rounded-full flex items-center justify-center shrink-0">
                <i className="fas fa-info-circle text-black text-2xl"></i>
              </div>
              <div>
                <h3 className="text-yellow-500 font-black text-lg uppercase italic tracking-widest">Instruções para Rendas</h3>
                <p className="text-gray-400 text-[10px] uppercase font-bold tracking-tighter">Preencha corretamente este campo</p>
              </div>
            </div>
            <div className="p-8">
              <ul className="space-y-6">
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5">
                    <span className="text-yellow-700 font-black text-xs">1</span>
                  </div>
                  <p className="text-gray-700 text-sm leading-relaxed">Preencha os próximos 12 meses com o <strong>mínimo</strong> que você garante que ganha.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5">
                    <span className="text-yellow-700 font-black text-xs">2</span>
                  </div>
                  <p className="text-gray-700 text-sm leading-relaxed">Conforme for ganhando mais ou menos, você vai atualizando mês a mês.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5">
                    <span className="text-yellow-700 font-black text-xs">3</span>
                  </div>
                  <p className="text-gray-700 text-sm leading-relaxed">Se fizer renda extra, basta adicionar uma linha e colocar o valor no mês que entrou ou vai entrar.</p>
                </li>
              </ul>
              <div className="mt-10 pt-6 border-t border-gray-100 flex flex-col gap-6">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <div onClick={() => handleToggleHideInstructions('income')} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${dontShowIncomeInstructionsAgain ? 'bg-yellow-500 border-yellow-500' : 'border-gray-300 group-hover:border-yellow-400'}`}>
                    {dontShowIncomeInstructionsAgain && <i className="fas fa-check text-[10px] text-black font-black"></i>}
                  </div>
                  <span className="text-gray-500 text-xs font-bold uppercase tracking-tight">Não mostrar essa mensagem novamente</span>
                </label>
                <button onClick={() => executeAddItem(CategoryType.INCOME)} className="w-full bg-zinc-900 hover:bg-zinc-800 text-yellow-500 font-black py-4 rounded-xl transition-all shadow-xl uppercase tracking-[0.2em] italic border border-yellow-500/20">Entendi e Continuar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Pop-up de Instruções para Cartão de Crédito */}
      {showCardInstructions && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden border border-yellow-500/30 animate-in zoom-in duration-300">
            <div className="bg-zinc-900 p-6 flex items-center gap-4 border-b border-yellow-600/30">
              <div className="w-12 h-12 bg-yellow-500 rounded-full flex items-center justify-center shrink-0">
                <i className="fas fa-credit-card text-black text-2xl"></i>
              </div>
              <div>
                <h3 className="text-yellow-500 font-black text-lg uppercase italic tracking-widest">Faturas de Cartão</h3>
                <p className="text-gray-400 text-[10px] uppercase font-bold tracking-tighter">Instruções de preenchimento</p>
              </div>
            </div>
            <div className="p-8">
              <p className="text-gray-700 text-sm leading-relaxed mb-6 italic">"Não precisa detalhar a fatura, é só colocar o valor total da fatura na hora que você está preenchendo essa planilha."</p>
              <div className="bg-gray-50 rounded-xl p-4 border border-gray-100 mb-8">
                <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3">Simulação de Preenchimento:</p>
                <div className="space-y-2">
                  <div className="flex justify-between items-center text-xs">
                    <span className="font-bold text-gray-600">Descrição:</span>
                    <span className="text-zinc-900 font-medium italic">Banco Inter (Fatura Total)</span>
                  </div>
                  <div className="grid grid-cols-5 gap-2 mt-2">
                    {[799, 699, 399, 299, 0].map((v, i) => (
                      <div key={i} className="flex flex-col items-center p-1.5 bg-white rounded border border-gray-100">
                        <span className="text-[8px] text-gray-400 uppercase font-bold">Mês {i+1}</span>
                        <span className={`text-[10px] font-black ${v > 0 ? 'text-yellow-600' : 'text-gray-300'}`}>{v}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
              <div className="mt-10 pt-6 border-t border-gray-100 flex flex-col gap-6">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <div onClick={() => handleToggleHideInstructions('card')} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${dontShowCardInstructionsAgain ? 'bg-yellow-500 border-yellow-500' : 'border-gray-300 group-hover:border-yellow-400'}`}>
                    {dontShowCardInstructionsAgain && <i className="fas fa-check text-[10px] text-black font-black"></i>}
                  </div>
                  <span className="text-gray-500 text-xs font-bold uppercase tracking-tight">Não mostrar essa mensagem novamente</span>
                </label>
                <button onClick={() => executeAddItem(CategoryType.CREDIT_CARD)} className="w-full bg-zinc-900 hover:bg-zinc-800 text-yellow-500 font-black py-4 rounded-xl transition-all shadow-xl uppercase tracking-[0.2em] italic border border-yellow-500/20">Entendi e Continuar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Pop-up de Sugestão de Lazer */}
      {showLeisureSuggestion && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden border border-yellow-500/30 animate-in zoom-in duration-300">
            <div className="bg-zinc-900 p-6 flex items-center gap-4 border-b border-yellow-600/30">
              <div className="w-12 h-12 bg-yellow-500 rounded-full flex items-center justify-center shrink-0">
                <i className="fas fa-cocktail text-black text-2xl"></i>
              </div>
              <div>
                <h3 className="text-yellow-500 font-black text-lg uppercase italic tracking-widest">Lazer e Pessoal</h3>
                <p className="text-gray-400 text-[10px] uppercase font-bold tracking-tighter">O mundo ideal em equilíbrio</p>
              </div>
            </div>
            <div className="p-8">
              <p className="text-gray-700 text-sm leading-relaxed mb-6">
                Para manter sua jornada financeira saudável, o ideal é destinar no máximo <strong>15%</strong> da sua renda para lazer e gastos pessoais.
              </p>
              {averageIncome > 0 ? (
                <div className="bg-yellow-50 border border-yellow-100 rounded-xl p-6 text-center">
                  <p className="text-xs text-yellow-700 font-bold uppercase tracking-widest mb-2">Sugestão com base na sua renda:</p>
                  <p className="text-3xl font-black text-zinc-900 italic">
                    {formatCurrency(averageIncome * 0.15)}
                  </p>
                  <p className="text-[10px] text-yellow-600 font-medium mt-1 uppercase">(Equivale a 15% de {formatCurrency(averageIncome)})</p>
                </div>
              ) : (
                <div className="bg-gray-50 border border-gray-100 rounded-xl p-6 text-center">
                  <p className="text-xs text-gray-500 italic">Insira sua renda no bloco de Entradas para receber uma sugestão personalizada.</p>
                </div>
              )}
              <div className="mt-10 pt-6 border-t border-gray-100 flex flex-col gap-6">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <div onClick={() => handleToggleHideInstructions('leisure')} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${dontShowLeisureSuggestionAgain ? 'bg-yellow-500 border-yellow-500' : 'border-gray-300 group-hover:border-yellow-400'}`}>
                    {dontShowLeisureSuggestionAgain && <i className="fas fa-check text-[10px] text-black font-black"></i>}
                  </div>
                  <span className="text-gray-500 text-xs font-bold uppercase tracking-tight">Não mostrar essa mensagem novamente</span>
                </label>
                <button onClick={() => executeAddItem(CategoryType.PERSONAL_LEISURE)} className="w-full bg-zinc-900 hover:bg-zinc-800 text-yellow-500 font-black py-4 rounded-xl transition-all shadow-xl uppercase tracking-[0.2em] italic border border-yellow-500/20">Entendi e Continuar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <main className="max-w-[1600px] mx-auto px-4 md:px-8">
        <div className="mb-8 bg-zinc-900 border-l-4 border-yellow-600 p-4 rounded-r-lg flex items-center justify-between shadow-lg">
          <div className="flex items-center gap-3">
            <i className="fas fa-calendar-check text-yellow-500 text-xl"></i>
            <p className="text-gray-100 text-sm font-medium">Mantenha sua jornada ativa: atualize seus lançamentos semanalmente.</p>
          </div>
        </div>
        <Diagnosis summary={monthlySummaries[0]} monthName={months[0].monthName} />
        {[
          { title: "ENTRADAS (Rendas)", type: CategoryType.INCOME },
          { title: "FATURAS DE CARTÃO", type: CategoryType.CREDIT_CARD },
          { title: "CONTAS FIXAS", subtitle: "Coloque aqui apenas contas que são pagas após receber o salário", type: CategoryType.FIXED_EXPENSE },
          { title: "CONTAS VARIÁVEIS", type: CategoryType.VARIABLE_EXPENSE },
          { title: "LAZER E GASTOS PESSOAIS", type: CategoryType.PERSONAL_LEISURE }
        ].map(block => (
          <BlockSection 
            key={block.type} 
            title={block.title} 
            subtitle={block.subtitle}
            category={block.type} 
            items={items.filter(i => i.category === block.type)} 
            allCards={allCards}
            months={months} 
            startMonth={startMonth}
            onStartMonthChange={setStartMonth}
            onAddItem={handleAddItem} 
            onUpdateValue={handleUpdateValue} 
            onTogglePaid={handleTogglePaid} 
            onRemoveItem={handleRemoveItem} 
            onUpdateDescription={handleUpdateDescription} 
            onReplicateValue={handleReplicateValue}
            onLinkCard={handleLinkCard}
          />
        ))}
        <div className="bg-white rounded-xl shadow-sm overflow-hidden mt-12 mb-20 border border-gray-200">
          <div className="bg-zinc-900 p-4 border-b border-yellow-600/30 text-center">
            <h3 className="text-yellow-500 font-black text-lg uppercase tracking-widest italic">Resumo Estratégico</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-gray-50 text-gray-500">
                  <th className="p-4 min-w-[200px] uppercase font-bold text-xs tracking-tighter">Categoria</th>
                  {months.map((m, idx) => (
                    <th key={idx} className="p-4 text-center border-l border-gray-100">{m.monthName}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="text-gray-900">
                <tr className="border-b">
                  <td className="p-4 font-bold text-green-600 bg-green-50">ENTRADAS TOTAIS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l bg-green-50">{formatCurrency(s.totalIncome)}</td>
                  ))}
                </tr>
                {['CARTÕES DE CRÉDITO', 'CONTAS FIXAS', 'CONTAS VARIÁVEIS', 'LAZER / GASTOS PESSOAIS'].map((cat, i) => (
                   <tr key={cat} className="border-b text-gray-600">
                    <td className="p-4">{cat}</td>
                    {monthlySummaries.map((s, idx) => {
                      const vals = [s.totalCreditCard, s.totalFixed, s.totalVariable, s.totalLeisure];
                      return <td key={idx} className="p-4 text-center border-l">{formatCurrency(vals[i])}</td>
                    })}
                   </tr>
                ))}
                <tr className="border-b bg-gray-50">
                  <td className="p-4 font-bold text-gray-700">TOTAL DE CUSTOS (SEM DUPLICIDADE)</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l font-bold">{formatCurrency(s.totalCost)}</td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="p-4 font-bold uppercase text-xs">SOBRA/FALTA NO MÊS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l font-bold ${s.balance >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                      {formatCurrency(s.balance)}
                    </td>
                  ))}
                </tr>
                <tr className="bg-zinc-900 text-white">
                  <td className="p-4 font-black uppercase text-yellow-500 text-sm italic">ACUMULATIVO</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l border-zinc-800 font-black text-lg ${s.accumulated >= 0 ? 'text-yellow-500' : 'text-red-400'}`}>
                      {formatCurrency(s.accumulated)}
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
          <div className="p-4 bg-gray-100 text-[10px] text-gray-500 italic flex flex-col gap-1">
            <p>* <strong>Contas Parceladas no Cartão:</strong> São deduzidas do custo real em todos os meses (já estão na fatura futura).</p>
            <p>* <strong>Contas Recorrentes no Cartão:</strong> São deduzidas do custo real apenas no mês atual (assumindo que entrarão na fatura futura conforme o tempo passar).</p>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { CategoryType, FinanceItem, SummaryData, LinkType } from './types';
import { getNext12Months, formatCurrency, MONTHS_BR } from './constants';
import BlockSection from './components/BlockSection';
import Diagnosis from './components/Diagnosis';

const DEFAULT_FIXED_EXPENSES = [
  'Moradia', 'Condominio', 'Telefone fixo', 'Internet', 'Celular',
  'Compras mercado (média mensal)', 'Gás', 'Luz', 'Água', 'Convênio',
  'Gasolina/uber (media mensal)', 'Iptu (mensal)', 'Educação',
  'Unha e sobrancelha', 'Academia', 'Cabelo', 'Estética', 'Dízimo',
  'Diarista', 'Comida pet', 'Banho pet', 'Personal', 'Netflix', 'Spotify',
  'Emprestimo (parcela mensal)', 'Previdência', 'Parcela seguro carro',
  'Parcela de carro', 'Terapia', 'Emprestimo'
];

const App: React.FC = () => {
  const [startMonth, setStartMonth] = useState<number>(() => {
    const saved = localStorage.getItem('finance_start_month');
    return saved ? parseInt(saved) : new Date().getMonth();
  });

  const months = useMemo(() => getNext12Months(startMonth), [startMonth]);

  const [items, setItems] = useState<FinanceItem[]>(() => {
    const saved = localStorage.getItem('finance_data');
    if (saved) return JSON.parse(saved);

    return DEFAULT_FIXED_EXPENSES.map((desc, idx) => ({
      id: `default-fixed-${idx}`,
      description: desc,
      category: CategoryType.FIXED_EXPENSE,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    }));
  });

  const [reminderDays, setReminderDays] = useState<number>(3);
  const [showReminderConfig, setShowReminderConfig] = useState(false);

  const [showIncomeInstructions, setShowIncomeInstructions] = useState(false);
  const [showCardInstructions, setShowCardInstructions] = useState(false);
  const [showLeisureSuggestion, setShowLeisureSuggestion] = useState(false);

  const [dontShowIncomeInstructionsAgain, setDontShowIncomeInstructionsAgain] = useState(() => {
    return localStorage.getItem('hide_income_instructions') === 'true';
  });
  const [dontShowCardInstructionsAgain, setDontShowCardInstructionsAgain] = useState(() => {
    return localStorage.getItem('hide_card_instructions') === 'true';
  });
  const [dontShowLeisureSuggestionAgain, setDontShowLeisureSuggestionAgain] = useState(() => {
    return localStorage.getItem('hide_leisure_suggestion') === 'true';
  });

  useEffect(() => { 
    localStorage.setItem('finance_data', JSON.stringify(items)); 
  }, [items]);

  useEffect(() => {
    localStorage.setItem('finance_start_month', startMonth.toString());
  }, [startMonth]);

  const averageIncome = useMemo(() => {
    const incomeItems = items.filter(i => i.category === CategoryType.INCOME);
    if (incomeItems.length === 0) return 0;
    const total = incomeItems.reduce((acc, item) => acc + (item.values[0] || 0), 0);
    return total;
  }, [items]);

  const handleAddItem = (category: CategoryType) => {
    if (category === CategoryType.INCOME && !dontShowIncomeInstructionsAgain) {
      setShowIncomeInstructions(true);
      return;
    }
    if (category === CategoryType.CREDIT_CARD && !dontShowCardInstructionsAgain) {
      setShowCardInstructions(true);
      return;
    }
    if (category === CategoryType.PERSONAL_LEISURE && !dontShowLeisureSuggestionAgain) {
      setShowLeisureSuggestion(true);
      return;
    }
    executeAddItem(category);
  };

  const executeAddItem = (category: CategoryType) => {
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: category === CategoryType.PERSONAL_LEISURE ? 'Lazer e Gastos Pessoais' : '', 
      category,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    };
    setItems(prev => [...prev, newItem]);
    setShowIncomeInstructions(false);
    setShowCardInstructions(false);
    setShowLeisureSuggestion(false);
  };

  const handleToggleHideInstructions = (type: 'income' | 'card' | 'leisure') => {
    if (type === 'income') {
      const newValue = !dontShowIncomeInstructionsAgain;
      setDontShowIncomeInstructionsAgain(newValue);
      localStorage.setItem('hide_income_instructions', newValue.toString());
    } else if (type === 'card') {
      const newValue = !dontShowCardInstructionsAgain;
      setDontShowCardInstructionsAgain(newValue);
      localStorage.setItem('hide_card_instructions', newValue.toString());
    } else {
      const newValue = !dontShowLeisureSuggestionAgain;
      setDontShowLeisureSuggestionAgain(newValue);
      localStorage.setItem('hide_leisure_suggestion', newValue.toString());
    }
  };

  const handleUpdateValue = (id: string, monthIdx: number, value: string) => {
    const numericValue = value === '' ? 0 : parseFloat(value);
    setItems(prev => prev.map(item => item.id === id ? { ...item, values: item.values.map((v, i) => i === monthIdx ? numericValue : v) } : item));
  };

  const handleUpdateDescription = (id: string, desc: string) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, description: desc } : item));
  };

  const handleTogglePaid = (id: string, monthIdx: number) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, paidStatus: item.paidStatus.map((s, i) => i === monthIdx ? !s : s) } : item));
  };

  const handleRemoveItem = (id: string) => {
    if (confirm('Deseja realmente excluir este item?')) {
      setItems(prev => prev.filter(item => item.id !== id));
    }
  };

  const handleReplicateValue = (id: string, monthIdx: number) => {
    setItems(prev => prev.map(i => {
      if (i.id !== id) return i;
      const valueToReplicate = i.values[monthIdx];
      return { ...i, values: i.values.map((v, idx) => idx >= monthIdx ? valueToReplicate : v) };
    }));
  };

  const handleLinkCard = (itemId: string, cardId: string, linkType?: LinkType) => {
    setItems(prev => prev.map(item => item.id === itemId ? { 
      ...item, 
      linkedCardId: cardId || undefined,
      linkType: cardId ? (linkType || LinkType.RECURRING) : undefined 
    } : item));
  };

  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;
    for (let m = 0; m < 12; m++) {
      const totalIncome = items.filter(i => i.category === CategoryType.INCOME).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCreditCardBruto = items.filter(i => i.category === CategoryType.CREDIT_CARD).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixed = items.filter(i => i.category === CategoryType.FIXED_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalFixedDuplicado = items.filter(i => {
        if (i.category !== CategoryType.FIXED_EXPENSE || !i.linkedCardId) return false;
        if (m === 0) return true;
        return i.linkType === LinkType.INSTALLMENT;
      }).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalVariable = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariableDuplicado = items.filter(i => {
        if (i.category !== CategoryType.VARIABLE_EXPENSE || !i.linkedCardId) return false;
        if (m === 0) return true;
        return i.linkType === LinkType.INSTALLMENT;
      }).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalLeisure = items.filter(i => i.category === CategoryType.PERSONAL_LEISURE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const realFixed = totalFixed - totalFixedDuplicado;
      const realVariable = totalVariable - totalVariableDuplicado;

      const totalCost = totalCreditCardBruto + realFixed + realVariable + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;

      summaries.push({ totalIncome, totalCreditCard: totalCreditCardBruto, totalFixed, totalVariable, totalLeisure, totalCost, balance, accumulated });
    }
    return summaries;
  }, [items]);

  const allCards = useMemo(() => items.filter(i => i.category === CategoryType.CREDIT_CARD), [items]);

  return (
    <div className="min-h-screen pb-20 bg-gray-50 text-gray-900">
      <header className="bg-[#0f0f0f] text-white p-8 shadow-2xl mb-8 sticky top-0 z-50 border-b-2 border-yellow-600/50">
        <div className="max-w-7xl mx-auto flex flex-col items-center gap-6 text-center">
          <div className="relative group">
            <div className="flex flex-col items-center">
              <div className="flex items-center gap-2">
                <span className="text-5xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-yellow-200 via-yellow-500 to-yellow-700 uppercase italic">RICO</span>
                <div className="w-14 h-14 border-2 border-yellow-500 rounded-full flex items-center justify-center relative shadow-[0_0_15px_rgba(234,179,8,0.3)]">
                  <i className="fas fa-sack-dollar text-yellow-500 text-3xl"></i>
                </div>
              </div>
              <div className="mt-[-8px]">
                <span className="text-2xl font-light tracking-[0.2em] text-gray-100 ml-4 lowercase">nessa vida</span>
              </div>
            </div>
          </div>

          <p className="text-yellow-500/80 text-xs md:text-sm uppercase tracking-[0.25em] font-medium max-w-lg">
            Uma vida financeiramente saudável é uma questão de escolha
          </p>

          <div className="absolute right-8 top-8 hidden lg:flex items-center gap-4 bg-zinc-900 p-2 rounded-lg border border-yellow-500/20">
            <div className="text-xs flex items-center gap-2">
              <i className="fas fa-bell text-yellow-500"></i>
              <span className="text-gray-400">Lembrete: {reminderDays} dias</span>
            </div>
            <button onClick={() => setShowReminderConfig(!showReminderConfig)} className="text-[10px] bg-yellow-600 hover:bg-yellow-500 text-black font-bold px-3 py-1 rounded transition-all">CONFIGURAR</button>
          </div>
        </div>

        {showReminderConfig && (
          <div className="max-w-md mx-auto mt-6 p-4 bg-zinc-800 rounded-lg border border-yellow-500/30 shadow-xl">
            <p className="text-xs mb-3 text-yellow-500 font-bold uppercase tracking-widest text-center">Intervalo de atualização</p>
            <div className="flex gap-2 justify-center">
              {[2, 3, 5, 7].map(d => (
                <button key={d} onClick={() => { setReminderDays(d); setShowReminderConfig(false); }} className={`px-4 py-2 rounded text-xs font-bold transition-all ${reminderDays === d ? 'bg-yellow-600 text-black' : 'bg-zinc-700 text-gray-300 hover:bg-zinc-600'}`}>
                  {d} dias
                </button>
              ))}
            </div>
          </div>
        )}
      </header>

      {showIncomeInstructions && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden border border-yellow-500/30 animate-in zoom-in duration-300">
            <div className="bg-zinc-900 p-6 flex items-center gap-4 border-b border-yellow-600/30">
              <div className="w-12 h-12 bg-yellow-500 rounded-full flex items-center justify-center shrink-0">
                <i className="fas fa-info-circle text-black text-2xl"></i>
              </div>
              <div>
                <h3 className="text-yellow-500 font-black text-lg uppercase italic tracking-widest">Instruções para Rendas</h3>
                <p className="text-gray-400 text-[10px] uppercase font-bold tracking-tighter">Preencha corretamente este campo</p>
              </div>
            </div>
            <div className="p-8">
              <ul className="space-y-6">
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5"><span className="text-yellow-700 font-black text-xs">1</span></div>
                  <p className="text-gray-700 text-sm leading-relaxed">Preencha os próximos 12 meses com o <strong>mínimo</strong> que você garante que ganha.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5"><span className="text-yellow-700 font-black text-xs">2</span></div>
                  <p className="text-gray-700 text-sm leading-relaxed">Conforme for ganhando mais ou menos, você vai atualizando mês a mês.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5"><span className="text-yellow-700 font-black text-xs">3</span></div>
                  <p className="text-gray-700 text-sm leading-relaxed">Se fizer renda extra, basta adicionar uma linha e colocar o valor no mês que entrou ou vai entrar.</p>
                </li>
              </ul>
              <div className="mt-10 pt-6 border-t border-gray-100 flex flex-col gap-6">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <div onClick={() => handleToggleHideInstructions('income')} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${dontShowIncomeInstructionsAgain ? 'bg-yellow-500 border-yellow-500' : 'border-gray-300 group-hover:border-yellow-400'}`}>
                    {dontShowIncomeInstructionsAgain && <i className="fas fa-check text-[10px] text-black font-black"></i>}
                  </div>
                  <span className="text-gray-500 text-xs font-bold uppercase tracking-tight">Não mostrar essa mensagem novamente</span>
                </label>
                <button onClick={() => executeAddItem(CategoryType.INCOME)} className="w-full bg-zinc-900 hover:bg-zinc-800 text-yellow-500 font-black py-4 rounded-xl transition-all shadow-xl uppercase tracking-[0.2em] italic border border-yellow-500/20">Entendi e Continuar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showCardInstructions && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden border border-yellow-500/30 animate-in zoom-in duration-300">
            <div className="bg-zinc-900 p-6 flex items-center gap-4 border-b border-yellow-600/30">
              <div className="w-12 h-12 bg-yellow-500 rounded-full flex items-center justify-center shrink-0"><i className="fas fa-credit-card text-black text-2xl"></i></div>
              <div>
                <h3 className="text-yellow-500 font-black text-lg uppercase italic tracking-widest">Faturas de Cartão</h3>
                <p className="text-gray-400 text-[10px] uppercase font-bold tracking-tighter">Instruções de preenchimento</p>
              </div>
            </div>
            <div className="p-8">
              <p className="text-gray-700 text-sm leading-relaxed mb-6 italic">"Não precisa detalhar a fatura, é só colocar o valor total da fatura na hora que você está preenchendo essa planilha."</p>
              <div className="bg-gray-50 rounded-xl p-4 border border-gray-100 mb-8">
                <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-3">Simulação de Preenchimento:</p>
                <div className="space-y-2">
                  <div className="flex justify-between items-center text-xs">
                    <span className="font-bold text-gray-600">Descrição:</span>
                    <span className="text-zinc-900 font-medium italic">Banco Inter (Fatura Total)</span>
                  </div>
                  <div className="grid grid-cols-5 gap-2 mt-2">
                    {[799, 699, 399, 299, 0].map((v, i) => (
                      <div key={i} className="flex flex-col items-center p-1.5 bg-white rounded border border-gray-100">
                        <span className="text-[8px] text-gray-400 uppercase font-bold">Mês {i+1}</span>
                        <span className={`text-[10px] font-black ${v > 0 ? 'text-yellow-600' : 'text-gray-300'}`}>{v}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
              <div className="mt-10 pt-6 border-t border-gray-100 flex flex-col gap-6">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <div onClick={() => handleToggleHideInstructions('card')} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${dontShowCardInstructionsAgain ? 'bg-yellow-500 border-yellow-500' : 'border-gray-300 group-hover:border-yellow-400'}`}>
                    {dontShowCardInstructionsAgain && <i className="fas fa-check text-[10px] text-black font-black"></i>}
                  </div>
                  <span className="text-gray-500 text-xs font-bold uppercase tracking-tight">Não mostrar essa mensagem novamente</span>
                </label>
                <button onClick={() => executeAddItem(CategoryType.CREDIT_CARD)} className="w-full bg-zinc-900 hover:bg-zinc-800 text-yellow-500 font-black py-4 rounded-xl transition-all shadow-xl uppercase tracking-[0.2em] italic border border-yellow-500/20">Entendi e Continuar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {showLeisureSuggestion && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden border border-yellow-500/30 animate-in zoom-in duration-300">
            <div className="bg-zinc-900 p-6 flex items-center gap-4 border-b border-yellow-600/30">
              <div className="w-12 h-12 bg-yellow-500 rounded-full flex items-center justify-center shrink-0"><i className="fas fa-cocktail text-black text-2xl"></i></div>
              <div>
                <h3 className="text-yellow-500 font-black text-lg uppercase italic tracking-widest">Lazer e Pessoal</h3>
                <p className="text-gray-400 text-[10px] uppercase font-bold tracking-tighter">O mundo ideal em equilíbrio</p>
              </div>
            </div>
            <div className="p-8">
              <p className="text-gray-700 text-sm leading-relaxed mb-6">Para manter sua jornada financeira saudável, o ideal é destinar no máximo <strong>15%</strong> da sua renda para lazer e gastos pessoais.</p>
              {averageIncome > 0 ? (
                <div className="bg-yellow-50 border border-yellow-100 rounded-xl p-6 text-center">
                  <p className="text-xs text-yellow-700 font-bold uppercase tracking-widest mb-2">Sugestão com base na sua renda:</p>
                  <p className="text-3xl font-black text-zinc-900 italic">{formatCurrency(averageIncome * 0.15)}</p>
                  <p className="text-[10px] text-yellow-600 font-medium mt-1 uppercase">(Equivale a 15% de {formatCurrency(averageIncome)})</p>
                </div>
              ) : (
                <div className="bg-gray-50 border border-gray-100 rounded-xl p-6 text-center">
                  <p className="text-xs text-gray-500 italic">Insira sua renda no bloco de Entradas para receber uma sugestão personalizada.</p>
                </div>
              )}
              <div className="mt-10 pt-6 border-t border-gray-100 flex flex-col gap-6">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <div onClick={() => handleToggleHideInstructions('leisure')} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${dontShowLeisureSuggestionAgain ? 'bg-yellow-500 border-yellow-500' : 'border-gray-300 group-hover:border-yellow-400'}`}>
                    {dontShowLeisureSuggestionAgain && <i className="fas fa-check text-[10px] text-black font-black"></i>}
                  </div>
                  <span className="text-gray-500 text-xs font-bold uppercase tracking-tight">Não mostrar essa mensagem novamente</span>
                </label>
                <button onClick={() => executeAddItem(CategoryType.PERSONAL_LEISURE)} className="w-full bg-zinc-900 hover:bg-zinc-800 text-yellow-500 font-black py-4 rounded-xl transition-all shadow-xl uppercase tracking-[0.2em] italic border border-yellow-500/20">Entendi e Continuar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <main className="max-w-[1600px] mx-auto px-4 md:px-8">
        <div className="mb-8 bg-zinc-900 border-l-4 border-yellow-600 p-4 rounded-r-lg flex items-center justify-between shadow-lg">
          <div className="flex items-center gap-3">
            <i className="fas fa-calendar-check text-yellow-500 text-xl"></i>
            <p className="text-gray-100 text-sm font-medium">Mantenha sua jornada ativa: atualize seus lançamentos semanalmente.</p>
          </div>
        </div>
        <Diagnosis summary={monthlySummaries[0]} monthName={months[0].monthName} />
        {[
          { title: "ENTRADAS (Rendas)", type: CategoryType.INCOME },
          { title: "FATURAS DE CARTÃO", type: CategoryType.CREDIT_CARD },
          { title: "CONTAS FIXAS", subtitle: "Coloque aqui apenas contas que são pagas após receber o salário", type: CategoryType.FIXED_EXPENSE },
          { title: "CONTAS VARIÁVEIS", type: CategoryType.VARIABLE_EXPENSE },
          { title: "LAZER E GASTOS PESSOAIS", type: CategoryType.PERSONAL_LEISURE }
        ].map(block => (
          <BlockSection 
            key={block.type} 
            title={block.title} 
            subtitle={block.subtitle}
            category={block.type} 
            items={items.filter(i => i.category === block.type)} 
            allCards={allCards}
            months={months} 
            startMonth={startMonth}
            onStartMonthChange={setStartMonth}
            onAddItem={handleAddItem} 
            onUpdateValue={handleUpdateValue} 
            onTogglePaid={handleTogglePaid} 
            onRemoveItem={handleRemoveItem} 
            onUpdateDescription={handleUpdateDescription} 
            onReplicateValue={handleReplicateValue}
            onLinkCard={handleLinkCard}
          />
        ))}
        <div className="bg-white rounded-xl shadow-sm overflow-hidden mt-12 mb-20 border border-gray-200">
          <div className="bg-zinc-900 p-4 border-b border-yellow-600/30 text-center">
            <h3 className="text-yellow-500 font-black text-lg uppercase tracking-widest italic">Resumo Estratégico</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-gray-50 text-gray-500">
                  <th className="p-4 min-w-[200px] uppercase font-bold text-xs tracking-tighter">Categoria</th>
                  {months.map((m, idx) => (
                    <th key={idx} className="p-4 text-center border-l border-gray-100">{m.monthName}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="text-gray-900">
                <tr className="border-b">
                  <td className="p-4 font-bold text-green-600 bg-green-50">ENTRADAS TOTAIS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l bg-green-50">{formatCurrency(s.totalIncome)}</td>
                  ))}
                </tr>
                {['CARTÕES DE CRÉDITO', 'CONTAS FIXAS', 'CONTAS VARIÁVEIS', 'LAZER / GASTOS PESSOAIS'].map((cat, i) => (
                   <tr key={cat} className="border-b text-gray-600">
                    <td className="p-4">{cat}</td>
                    {monthlySummaries.map((s, idx) => {
                      const vals = [s.totalCreditCard, s.totalFixed, s.totalVariable, s.totalLeisure];
                      return <td key={idx} className="p-4 text-center border-l">{formatCurrency(vals[i])}</td>
                    })}
                   </tr>
                ))}
                <tr className="border-b bg-gray-50">
                  <td className="p-4 font-bold text-gray-700">TOTAL DE CUSTOS (SEM DUPLICIDADE)</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className="p-4 text-center border-l font-bold">{formatCurrency(s.totalCost)}</td>
                  ))}
                </tr>
                <tr className="border-b">
                  <td className="p-4 font-bold uppercase text-xs">SOBRA/FALTA NO MÊS</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l font-bold ${s.balance >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                      {formatCurrency(s.balance)}
                    </td>
                  ))}
                </tr>
                <tr className="bg-zinc-900 text-white">
                  <td className="p-4 font-black uppercase text-yellow-500 text-sm italic">ACUMULATIVO</td>
                  {monthlySummaries.map((s, idx) => (
                    <td key={idx} className={`p-4 text-center border-l border-zinc-800 font-black text-lg ${s.accumulated >= 0 ? 'text-yellow-500' : 'text-red-400'}`}>
                      {formatCurrency(s.accumulated)}
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
          <div className="p-4 bg-gray-100 text-[10px] text-gray-500 italic flex flex-col gap-1">
            <p>* <strong>Contas Parceladas no Cartão:</strong> São deduzidas do custo real em todos os meses (já estão na fatura futura).</p>
            <p>* <strong>Contas Recorrentes no Cartão:</strong> São deduzidas do custo real apenas no mês atual (assumindo que entrarão na fatura futura conforme o tempo passar).</p>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { CategoryType, FinanceItem, SummaryData, LinkType } from './types';
import { getNext12Months, formatCurrency, MONTHS_BR } from './constants';
import BlockSection from './components/BlockSection';
import Diagnosis from './components/Diagnosis';

const DEFAULT_FIXED_EXPENSES = [
  'Moradia', 'Condominio', 'Telefone fixo', 'Internet', 'Celular',
  'Compras mercado (média mensal)', 'Gás', 'Luz', 'Água', 'Convênio',
  'Gasolina/uber (media mensal)', 'Iptu (mensal)', 'Educação',
  'Unha e sobrancelha', 'Academia', 'Cabelo', 'Estética', 'Dízimo',
  'Diarista', 'Comida pet', 'Banho pet', 'Personal', 'Netflix', 'Spotify',
  'Emprestimo (parcela mensal)', 'Previdência', 'Parcela seguro carro',
  'Parcela de carro', 'Terapia', 'Emprestimo'
];

const App: React.FC = () => {
  const [startMonth, setStartMonth] = useState<number>(() => {
    const saved = localStorage.getItem('finance_start_month');
    return saved ? parseInt(saved) : new Date().getMonth();
  });

  const months = useMemo(() => getNext12Months(startMonth), [startMonth]);

  const [items, setItems] = useState<FinanceItem[]>(() => {
    const saved = localStorage.getItem('finance_data');
    if (saved) return JSON.parse(saved);

    return DEFAULT_FIXED_EXPENSES.map((desc, idx) => ({
      id: `default-fixed-${idx}`,
      description: desc,
      category: CategoryType.FIXED_EXPENSE,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    }));
  });

  const [reminderDays, setReminderDays] = useState<number>(3);
  const [showReminderConfig, setShowReminderConfig] = useState(false);

  const [showIncomeInstructions, setShowIncomeInstructions] = useState(false);
  const [showCardInstructions, setShowCardInstructions] = useState(false);
  const [showLeisureSuggestion, setShowLeisureSuggestion] = useState(false);
  const [showMigrationAlert, setShowMigrationAlert] = useState<{show: boolean, itemName: string}>({show: false, itemName: ''});

  const [dontShowIncomeInstructionsAgain, setDontShowIncomeInstructionsAgain] = useState(() => {
    return localStorage.getItem('hide_income_instructions') === 'true';
  });
  const [dontShowCardInstructionsAgain, setDontShowCardInstructionsAgain] = useState(() => {
    return localStorage.getItem('hide_card_instructions') === 'true';
  });
  const [dontShowLeisureSuggestionAgain, setDontShowLeisureSuggestionAgain] = useState(() => {
    return localStorage.getItem('hide_leisure_suggestion') === 'true';
  });

  useEffect(() => { 
    localStorage.setItem('finance_data', JSON.stringify(items)); 
  }, [items]);

  useEffect(() => {
    localStorage.setItem('finance_start_month', startMonth.toString());
  }, [startMonth]);

  const averageIncome = useMemo(() => {
    const incomeItems = items.filter(i => i.category === CategoryType.INCOME);
    if (incomeItems.length === 0) return 0;
    const total = incomeItems.reduce((acc, item) => acc + (item.values[0] || 0), 0);
    return total;
  }, [items]);

  const handleAddItem = (category: CategoryType) => {
    if (category === CategoryType.INCOME && !dontShowIncomeInstructionsAgain) {
      setShowIncomeInstructions(true);
      return;
    }
    if (category === CategoryType.CREDIT_CARD && !dontShowCardInstructionsAgain) {
      setShowCardInstructions(true);
      return;
    }
    if (category === CategoryType.PERSONAL_LEISURE && !dontShowLeisureSuggestionAgain) {
      setShowLeisureSuggestion(true);
      return;
    }
    executeAddItem(category);
  };

  const executeAddItem = (category: CategoryType) => {
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: category === CategoryType.PERSONAL_LEISURE ? 'Lazer e Gastos Pessoais' : '', 
      category,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    };
    setItems(prev => [...prev, newItem]);
    setShowIncomeInstructions(false);
    setShowCardInstructions(false);
    setShowLeisureSuggestion(false);
  };

  const handleToggleHideInstructions = (type: 'income' | 'card' | 'leisure') => {
    if (type === 'income') {
      const newValue = !dontShowIncomeInstructionsAgain;
      setDontShowIncomeInstructionsAgain(newValue);
      localStorage.setItem('hide_income_instructions', newValue.toString());
    } else if (type === 'card') {
      const newValue = !dontShowCardInstructionsAgain;
      setDontShowCardInstructionsAgain(newValue);
      localStorage.setItem('hide_card_instructions', newValue.toString());
    } else {
      const newValue = !dontShowLeisureSuggestionAgain;
      setDontShowLeisureSuggestionAgain(newValue);
      localStorage.setItem('hide_leisure_suggestion', newValue.toString());
    }
  };

  const handleUpdateValue = (id: string, monthIdx: number, value: string) => {
    const numericValue = value === '' ? 0 : parseFloat(value);

    setItems(prev => {
      const updatedItems = prev.map(item => 
        item.id === id ? { ...item, values: item.values.map((v, i) => i === monthIdx ? numericValue : v) } : item
      );

      // Check for migration logic from Fixed to Variable
      const targetItem = updatedItems.find(i => i.id === id);
      if (targetItem && targetItem.category === CategoryType.FIXED_EXPENSE) {
        const filledMonths = targetItem.values.filter(v => v > 0).length;
        // Logic: if it's "ending" (not all 12 months filled) and has less than 10 installments
        if (filledMonths > 0 && filledMonths < 10) {
          setShowMigrationAlert({ show: true, itemName: targetItem.description || 'este item' });
          return updatedItems.map(item => 
            item.id === id ? { ...item, category: CategoryType.VARIABLE_EXPENSE } : item
          );
        }
      }

      return updatedItems;
    });
  };

  const handleUpdateDescription = (id: string, desc: string) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, description: desc } : item));
  };

  const handleTogglePaid = (id: string, monthIdx: number) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, paidStatus: item.paidStatus.map((s, i) => i === monthIdx ? !s : s) } : item));
  };

  const handleRemoveItem = (id: string) => {
    if (confirm('Deseja realmente excluir este item?')) {
      setItems(prev => prev.filter(item => item.id !== id));
    }
  };

  const handleReplicateValue = (id: string, monthIdx: number) => {
    setItems(prev => prev.map(i => {
      if (i.id !== id) return i;
      const valueToReplicate = i.values[monthIdx];
      return { ...i, values: i.values.map((v, idx) => idx >= monthIdx ? valueToReplicate : v) };
    }));
  };

  const handleLinkCard = (itemId: string, cardId: string, linkType?: LinkType) => {
    setItems(prev => prev.map(item => item.id === itemId ? { 
      ...item, 
      linkedCardId: cardId || undefined,
      linkType: cardId ? (linkType || LinkType.RECURRING) : undefined 
    } : item));
  };

  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;
    for (let m = 0; m < 12; m++) {
      const totalIncome = items.filter(i => i.category === CategoryType.INCOME).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCreditCardBruto = items.filter(i => i.category === CategoryType.CREDIT_CARD).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixed = items.filter(i => i.category === CategoryType.FIXED_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalFixedDuplicado = items.filter(i => {
        if (i.category !== CategoryType.FIXED_EXPENSE || !i.linkedCardId) return false;
        if (m === 0) return true;
        return i.linkType === LinkType.INSTALLMENT;
      }).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalVariable = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariableDuplicado = items.filter(i => {
        if (i.category !== CategoryType.VARIABLE_EXPENSE || !i.linkedCardId) return false;
        if (m === 0) return true;
        return i.linkType === LinkType.INSTALLMENT;
      }).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const totalLeisure = items.filter(i => i.category === CategoryType.PERSONAL_LEISURE).reduce((sum, i) => sum + (i.values[m] || 0), 0);

      const realFixed = totalFixed - totalFixedDuplicado;
      const realVariable = totalVariable - totalVariableDuplicado;

      const totalCost = totalCreditCardBruto + realFixed + realVariable + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;

      summaries.push({ totalIncome, totalCreditCard: totalCreditCardBruto, totalFixed, totalVariable, totalLeisure, totalCost, balance, accumulated });
    }
    return summaries;
  }, [items]);

  const allCards = useMemo(() => items.filter(i => i.category === CategoryType.CREDIT_CARD), [items]);

  return (
    <div className="min-h-screen pb-20 bg-gray-50 text-gray-900">
      <header className="bg-[#0f0f0f] text-white p-8 shadow-2xl mb-8 sticky top-0 z-50 border-b-2 border-yellow-600/50">
        <div className="max-w-7xl mx-auto flex flex-col items-center gap-6 text-center">
          <div className="relative group">
            <div className="flex flex-col items-center">
              <div className="flex items-center gap-2">
                <span className="text-5xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-yellow-200 via-yellow-500 to-yellow-700 uppercase italic">RICO</span>
                <div className="w-14 h-14 border-2 border-yellow-500 rounded-full flex items-center justify-center relative shadow-[0_0_15px_rgba(234,179,8,0.3)]">
                  <i className="fas fa-sack-dollar text-yellow-500 text-3xl"></i>
                </div>
              </div>
              <div className="mt-[-8px]">
                <span className="text-2xl font-light tracking-[0.2em] text-gray-100 ml-4 lowercase">nessa vida</span>
              </div>
            </div>
          </div>

          <p className="text-yellow-500/80 text-xs md:text-sm uppercase tracking-[0.25em] font-medium max-w-lg">
            Uma vida financeiramente saudável é uma questão de escolha
          </p>

          <div className="absolute right-8 top-8 hidden lg:flex items-center gap-4 bg-zinc-900 p-2 rounded-lg border border-yellow-500/20">
            <div className="text-xs flex items-center gap-2">
              <i className="fas fa-bell text-yellow-500"></i>
              <span className="text-gray-400">Lembrete: {reminderDays} dias</span>
            </div>
            <button onClick={() => setShowReminderConfig(!showReminderConfig)} className="text-[10px] bg-yellow-600 hover:bg-yellow-500 text-black font-bold px-3 py-1 rounded transition-all">CONFIGURAR</button>
          </div>
        </div>

        {showReminderConfig && (
          <div className="max-w-md mx-auto mt-6 p-4 bg-zinc-800 rounded-lg border border-yellow-500/30 shadow-xl">
            <p className="text-xs mb-3 text-yellow-500 font-bold uppercase tracking-widest text-center">Intervalo de atualização</p>
            <div className="flex gap-2 justify-center">
              {[2, 3, 5, 7].map(d => (
                <button key={d} onClick={() => { setReminderDays(d); setShowReminderConfig(false); }} className={`px-4 py-2 rounded text-xs font-bold transition-all ${reminderDays === d ? 'bg-yellow-600 text-black' : 'bg-zinc-700 text-gray-300 hover:bg-zinc-600'}`}>
                  {d} dias
                </button>
              ))}
            </div>
          </div>
        )}
      </header>

      {/* Migration Alert Pop-up */}
      {showMigrationAlert.show && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden border-2 border-yellow-500 animate-in zoom-in duration-300">
            <div className="bg-zinc-900 p-6 flex items-center gap-4 border-b border-yellow-600/30 text-yellow-500">
              <i className="fas fa-exchange-alt text-2xl"></i>
              <h3 className="font-black text-lg uppercase italic tracking-widest">Migração Automática</h3>
            </div>
            <div className="p-8">
              <p className="text-gray-700 text-base leading-relaxed font-medium">
                O item <strong className="text-zinc-900 italic">"{showMigrationAlert.itemName}"</strong> possui menos de 10 parcelas preenchidas.
              </p>
              <p className="mt-4 text-gray-600 text-sm italic border-l-4 border-yellow-500 pl-4 py-2 bg-yellow-50/50">
                "Como você tem menos de 10 parcelas, este item será incluído automaticamente em <strong>Contas Variáveis</strong>. Contas Fixas são reservadas para pagamentos recorrentes ou com mais de 18 parcelas."
              </p>
              <button 
                onClick={() => setShowMigrationAlert({show: false, itemName: ''})} 
                className="mt-10 w-full bg-zinc-900 hover:bg-zinc-800 text-yellow-500 font-black py-4 rounded-xl transition-all shadow-xl uppercase tracking-widest"
              >
                Entendido
              </button>
            </div>
          </div>
        </div>
      )}

      {showIncomeInstructions && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden border border-yellow-500/30 animate-in zoom-in duration-300">
            <div className="bg-zinc-900 p-6 flex items-center gap-4 border-b border-yellow-600/30">
              <div className="w-12 h-12 bg-yellow-500 rounded-full flex items-center justify-center shrink-0">
                <i className="fas fa-info-circle text-black text-2xl"></i>
              </div>
              <div>
                <h3 className="text-yellow-500 font-black text-lg uppercase italic tracking-widest">Instruções para Rendas</h3>
                <p className="text-gray-400 text-[10px] uppercase font-bold tracking-tighter">Preencha corretamente este campo</p>
              </div>
            </div>
            <div className="p-8">
              <ul className="space-y-6">
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5"><span className="text-yellow-700 font-black text-xs">1</span></div>
                  <p className="text-gray-700 text-sm leading-relaxed">Preencha os próximos 12 meses com o <strong>mínimo</strong> que você garante que ganha.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5"><span className="text-yellow-700 font-black text-xs">2</span></div>
                  <p className="text-gray-700 text-sm leading-relaxed">Conforme for ganhando mais ou menos, você vai atualizando mês a mês.</p>
                </li>
                <li className="flex gap-4">
                  <div className="w-6 h-6 bg-yellow-100 rounded-full flex items-center justify-center shrink-0 mt-0.5"><span className="text-yellow-700 font-black text-xs">3</span></div>
                  <p className="text-gray-700 text-sm leading-relaxed">Se fizer renda extra, basta adicionar uma linha e colocar o valor no mês que entrou ou vai entrar.</p>
                </li>
              </ul>
              <div className="mt-10 pt-6 border-t border-gray-100 flex flex-col gap-6">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <div onClick={() => handleToggleHideInstructions('income')} className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${dontShowIncomeInstructionsAgain ? 'bg-yellow-500 border-yellow-500' : 'border-gray-300 group-hover:border-yellow-400'}`}>
