          <div>
            <h3 className="text-yellow-500 font-black text-xl uppercase italic tracking-tighter">Inteligência de Consumo</h3>
            <p className="text-gray-400 text-[10px] uppercase font-bold tracking-widest">Lançamentos rápidos para bater o teto</p>
