        <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
          <select 
            className="bg-zinc-800 text-white border-zinc-700 rounded-xl p-3 text-sm font-bold focus:ring-2 ring-yellow-500 outline-none transition-all"
            value={selectedItemId}
            onChange={(e) => setSelectedItemId(e.target.value)}
          >
            <option value="">Selecione o Gasto...</option>
            {suggestedItems.map(i => (
              <option key={i.id} value={i.id}>{i.description} (Teto: {formatCurrency(i.values[0])})</option>
            ))}
          </select>
          <input 
            type="text" 
            placeholder="O que comprou hoje?" 
            className="bg-zinc-800 text-white border-zinc-700 rounded-xl p-3 text-sm focus:ring-2 ring-yellow-500 outline-none"
            value={newDesc}
            onChange={(e) => setNewDesc(e.target.value)}
          />
          <input 
            type="number" 
            placeholder="Valor R$" 
            className="bg-zinc-800 text-white border-zinc-700 rounded-xl p-3 text-sm font-black focus:ring-2 ring-yellow-500 outline-none"
            value={newValue}
            onChange={(e) => setNewValue(e.target.value)}
          />
