            className="bg-yellow-600 hover:bg-yellow-500 disabled:opacity-50 disabled:hover:bg-yellow-600 text-black font-black rounded-xl transition-all uppercase text-xs tracking-widest shadow-lg shadow-yellow-600/20"
          >
            Lançar Agora
