        ) : (
          suggestedItems.map(item => {
            const partials = item.partialExpenses?.[monthKey] || [];
            const spent = partials.reduce((acc, p) => acc + p.value, 0);
            const limit = item.values[0];
            const remaining = limit - spent;
            const percent = (spent / limit) * 100;

            return (
              <div key={item.id} className="min-w-[280px] flex-shrink-0 bg-white rounded-2xl shadow-xl border border-gray-200 flex flex-col overflow-hidden">
