import React, { useState, useEffect } from 'react';
import { FinanceItem, PartialExpense, CategoryType } from '../types';
import { formatCurrency } from '../constants';

interface TetoGastosProps {
  items: FinanceItem[];
  currentMonthIdx: number;
  currentYear: number;
  onAddPartial: (itemId: string, expense: PartialExpense) => void;
  onRemovePartial: (itemId: string, expenseId: string) => void;
}

interface ColumnData {
  id: string;
  title: string;
  linkedItemId: string;
}

const TetoGastos: React.FC<TetoGastosProps> = ({ items, currentMonthIdx, currentYear, onAddPartial, onRemovePartial }) => {
  const monthKey = `${currentYear}-${currentMonthIdx}`;

  // Estado para as colunas da "Planilha"
  const [columns, setColumns] = useState<ColumnData[]>(() => {
    const saved = localStorage.getItem('teto_columns');
    return saved ? JSON.parse(saved) : [
      { id: '1', title: 'Despesa 1', linkedItemId: '' },
      { id: '2', title: 'Despesa 2', linkedItemId: '' },
      { id: '3', title: 'Despesa 3', linkedItemId: '' },
      { id: '4', title: 'Despesa 4', linkedItemId: '' }
    ];
  });

  useEffect(() => {
    localStorage.setItem('teto_columns', JSON.stringify(columns));
  }, [columns]);

  const addColumn = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    setColumns([...columns, { id: newId, title: `Despesa ${columns.length + 1}`, linkedItemId: '' }]);
  };

  const removeColumn = (id: string) => {
    if (columns.length <= 1) return;
    setColumns(columns.filter(c => c.id !== id));
  };

  const updateColumn = (id: string, field: keyof ColumnData, value: string) => {
    setColumns(columns.map(c => c.id === id ? { ...c, [field]: value } : c));
  };

  const handleValueEntry = (itemId: string, value: string) => {
    if (!itemId || value === '' || isNaN(parseFloat(value))) return;
    const expense: PartialExpense = {
      id: Math.random().toString(36).substr(2, 9),
      date: new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }),
      description: 'Lançamento',
      value: parseFloat(value)
    };
    onAddPartial(itemId, expense);
  };

  return (
    <div className="p-4 md:p-8 animate-in fade-in duration-500">
      <div className="mb-6 flex justify-between items-center bg-zinc-900 p-4 rounded-xl border-l-4 border-yellow-500">
        <div>
          <h2 className="text-yellow-500 font-black text-xl uppercase italic">Controle de Lançamentos</h2>
          <p className="text-gray-400 text-[10px] uppercase font-bold tracking-widest">Acompanhamento em tempo real vs. Planejado</p>
        </div>
        <button 
          onClick={addColumn}
          className="bg-yellow-600 hover:bg-yellow-500 text-black font-black px-4 py-2 rounded-lg text-xs uppercase transition-all shadow-lg"
        >
          <i className="fas fa-plus mr-2"></i> Nova Coluna
        </button>
      </div>

      <div className="flex gap-0 overflow-x-auto pb-10 scrollbar-thin scrollbar-thumb-yellow-600 scrollbar-track-zinc-800 border-l border-t border-black">
        {columns.map((col) => {
          const linkedItem = items.find(i => i.id === col.linkedItemId);
          const teto = linkedItem ? linkedItem.values[0] : 0;
          const partials = linkedItem?.partialExpenses?.[monthKey] || [];
          const totalSpent = partials.reduce((acc, p) => acc + p.value, 0);

          return (
            <div key={col.id} className="min-w-[200px] flex-shrink-0 flex flex-col group relative">
              {/* Título da Despesa (Cabeçalho Amarelo) */}
              <div className="bg-[#eab308] border-r border-b border-black p-0">
                <input 
                  type="text" 
                  value={col.title}
                  onChange={(e) => updateColumn(col.id, 'title', e.target.value)}
                  className="w-full bg-transparent border-none text-center font-black text-xs uppercase p-2 outline-none placeholder-black/50"
                  placeholder="NOME DESPESA"
                />
              </div>

              {/* Seletor de Vínculo (Sub-Cabeçalho Amarelo Escuro) */}
              <div className="bg-[#ca8a04] border-r border-b border-black p-0">
                <select 
                  className="w-full bg-transparent border-none text-[9px] font-bold uppercase p-1 text-center outline-none cursor-pointer"
                  value={col.linkedItemId}
                  onChange={(e) => updateColumn(col.id, 'linkedItemId', e.target.value)}
                >
                  <option value="">Vincular Item...</option>
                  {items.filter(i => i.category !== CategoryType.INCOME).map(i => (
                    <option key={i.id} value={i.id}>{i.description}</option>
                  ))}
                </select>
              </div>

              {/* Valor do Teto (Célula Amarela Brilhante) */}
              <div className="bg-[#ffff00] border-r border-b border-black p-2 text-center">
                <span className="text-xs font-black">{formatCurrency(teto)}</span>
              </div>

              {/* Linhas de Lançamento (Branco com bordas pretas) */}
              <div className="flex-grow flex flex-col bg-white">
                {/* Linha de entrada rápida */}
                <div className="border-r border-b border-black">
                  <input 
                    type="number" 
                    placeholder="Digitar gasto..."
                    className="w-full p-2 text-center text-xs outline-none bg-blue-50/30 focus:bg-blue-50 font-bold"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        handleValueEntry(col.linkedItemId, e.currentTarget.value);
                        e.currentTarget.value = '';
                      }
                    }}
                  />
                </div>

                {/* Lista de gastos já lançados */}
                {Array.from({ length: Math.max(15, partials.length) }).map((_, idx) => {
                  const p = partials[idx];
                  return (
                    <div key={idx} className="border-r border-b border-black h-8 flex items-center justify-center relative group/row">
                      {p ? (
                        <div className="w-full flex justify-between items-center px-2">
                          <span className="text-[9px] text-gray-400 font-mono">{p.date}</span>
                          <span className="text-xs font-bold text-zinc-800">{formatCurrency(p.value)}</span>
                          <button 
                            onClick={() => onRemovePartial(col.linkedItemId, p.id)}
                            className="opacity-0 group-hover/row:opacity-100 text-red-500 hover:scale-125 transition-all"
                          >
                            <i className="fas fa-times text-[10px]"></i>
                          </button>
                        </div>
                      ) : null}
                    </div>
                  );
                })}

                {/* Linha de Total (Borda Preta Forte) */}
                <div className="border-r border-b border-black h-10 bg-gray-50 flex items-center justify-center">
                  <span className={`font-black text-sm ${totalSpent > teto && teto > 0 ? 'text-red-600' : 'text-zinc-900'}`}>
                    {formatCurrency(totalSpent)}
                  </span>
                </div>
              </div>

              {/* Botão de Excluir Coluna */}
              <button 
                onClick={() => removeColumn(col.id)}
                className="absolute -top-2 -right-2 w-5 h-5 bg-red-600 text-white rounded-full flex items-center justify-center text-[10px] opacity-0 group-hover:opacity-100 transition-opacity shadow-lg z-10"
              >
                <i className="fas fa-trash"></i>
              </button>
            </div>
          );
        })}
      </div>

      <div className="mt-8 bg-zinc-900 rounded-2xl p-6 border-l-4 border-yellow-500 text-white flex items-center gap-6 shadow-2xl">
        <div className="w-16 h-16 bg-yellow-500 rounded-full flex items-center justify-center shrink-0 shadow-[0_0_20px_rgba(234,179,8,0.3)]">
          <i className="fas fa-lightbulb text-black text-2xl"></i>
        </div>
        <div>
          <h4 className="font-black text-lg uppercase italic text-yellow-500">Dica Rico Nessa Vida</h4>
          <p className="text-gray-400 text-sm leading-relaxed">
            "Para lançar um gasto nesta planilha, basta selecionar o item vinculado no cabeçalho amarelo e digitar o valor na primeira linha azul. Pressione <strong>ENTER</strong> para confirmar. O total no rodapé avisará se você está chegando perto do teto planejado."
          </p>
        </div>
      </div>
    </div>
  );
};

