import React, { useState, useEffect } from 'react';
import { FinanceItem, PartialExpense, CategoryType } from '../types';
import { formatCurrency } from '../constants';

interface TetoGastosProps {
  items: FinanceItem[];
  currentMonthIdx: number;
  currentYear: number;
  onAddPartial: (itemId: string, expense: PartialExpense) => void;
  onRemovePartial: (itemId: string, expenseId: string) => void;
}

interface ColumnData {
  id: string;
  title: string;
  linkedItemId: string;
}

const TetoGastos: React.FC<TetoGastosProps> = ({ items, currentMonthIdx, currentYear, onAddPartial, onRemovePartial }) => {
  const monthKey = `${currentYear}-${currentMonthIdx}`;

  const [columns, setColumns] = useState<ColumnData[]>(() => {
    const saved = localStorage.getItem('teto_columns_v2');
    return saved ? JSON.parse(saved) : [
      { id: '1', title: 'SUPERMERCADO', linkedItemId: '' },
      { id: '2', title: 'GASOLINA', linkedItemId: '' },
      { id: '3', title: 'LAZER', linkedItemId: '' },
      { id: '4', title: 'EXTRAS', linkedItemId: '' }
    ];
  });

  useEffect(() => {
    localStorage.setItem('teto_columns_v2', JSON.stringify(columns));
  }, [columns]);

  const addColumn = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    setColumns([...columns, { id: newId, title: `NOVA DESPESA`, linkedItemId: '' }]);
  };

  const removeColumn = (id: string) => {
    if (columns.length <= 1) return;
    setColumns(columns.filter(c => c.id !== id));
  };

  const updateColumn = (id: string, field: keyof ColumnData, value: string) => {
    setColumns(columns.map(c => c.id === id ? { ...c, [field]: value } : c));
  };

  const handleValueEntry = (itemId: string, value: string) => {
    if (!itemId || value === '' || isNaN(parseFloat(value))) return;
    const expense: PartialExpense = {
      id: Math.random().toString(36).substr(2, 9),
      date: new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }),
      description: 'Gasto mensal',
      value: parseFloat(value)
    };
    onAddPartial(itemId, expense);
  };

  return (
    <div className="p-2 md:p-6 animate-in fade-in zoom-in-95 duration-500">
      {/* Header Estilizado */}
      <div className="mb-8 flex flex-col md:flex-row justify-between items-start md:items-center bg-[#0a0a0a] p-6 rounded-2xl border border-zinc-800 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-1 h-full bg-yellow-500"></div>
        <div className="z-10">
          <h2 className="text-white font-black text-2xl uppercase italic tracking-tighter flex items-center gap-3">
            <span className="text-yellow-500"><i className="fas fa-bullseye"></i></span>
            Controle de Teto Mensal
          </h2>
          <p className="text-zinc-500 text-[10px] uppercase font-bold tracking-[0.2em] mt-1">Gestão de fluxo de caixa em tempo real</p>
        </div>
        <button 
          onClick={addColumn}
          className="mt-4 md:mt-0 z-10 bg-gradient-to-r from-yellow-600 to-yellow-400 hover:from-yellow-500 hover:to-yellow-300 text-black font-black px-6 py-3 rounded-xl text-xs uppercase transition-all shadow-[0_10px_20px_rgba(202,138,4,0.2)] active:scale-95 flex items-center gap-2"
        >
          <i className="fas fa-plus-circle"></i> Expandir Planilha
        </button>
      </div>

      {/* Grid de Colunas Premium */}
      <div className="flex gap-4 overflow-x-auto pb-8 pt-2 px-2 scrollbar-thin scrollbar-thumb-yellow-600 scrollbar-track-zinc-900">
        {columns.map((col) => {
          const linkedItem = items.find(i => i.id === col.linkedItemId);
          const teto = linkedItem ? linkedItem.values[0] : 0;
          const partials = linkedItem?.partialExpenses?.[monthKey] || [];
          const totalSpent = partials.reduce((acc, p) => acc + p.value, 0);
          const isOverLimit = totalSpent > teto && teto > 0;

          return (
            <div key={col.id} className="min-w-[260px] flex-shrink-0 flex flex-col group relative transition-all duration-300 hover:-translate-y-1">

              {/* Título (Cabeçalho Superior) */}
              <div className="bg-zinc-900 rounded-t-2xl border-x border-t border-zinc-800 p-1">
                <input 
                  type="text" 
                  value={col.title}
                  onChange={(e) => updateColumn(col.id, 'title', e.target.value)}
                  className="w-full bg-transparent border-none text-center font-black text-[11px] uppercase p-3 text-yellow-500 outline-none tracking-widest"
                  placeholder="DIGITE A CATEGORIA"
                />
              </div>

              {/* Seletor de Vínculo (Dropdown) */}
              <div className="bg-zinc-800 border-x border-zinc-700">
                <select 
                  className="w-full bg-transparent border-none text-[9px] font-bold uppercase p-2 text-center text-zinc-400 outline-none cursor-pointer hover:text-white transition-colors"
                  value={col.linkedItemId}
                  onChange={(e) => updateColumn(col.id, 'linkedItemId', e.target.value)}
                >
                  <option value="" className="bg-zinc-900">Vincular Planejamento...</option>
                  {items.filter(i => i.category !== CategoryType.INCOME).map(i => (
                    <option key={i.id} value={i.id} className="bg-zinc-900">{i.description}</option>
                  ))}
                </select>
              </div>

              {/* Célula do Teto (Highlight) */}
              <div className={`border-x border-zinc-700 p-4 text-center transition-all duration-500 ${isOverLimit ? 'bg-red-950/30' : 'bg-zinc-900'}`}>
                <p className="text-[8px] font-black text-zinc-500 uppercase tracking-widest mb-1">Limite Disponível</p>
                <div className={`text-lg font-black font-mono transition-all ${isOverLimit ? 'text-red-500 animate-pulse' : 'text-white'}`}>
                  {formatCurrency(teto)}
                </div>
              </div>

              {/* Input de Lançamento (Foco Central) */}
              <div className="bg-white border-x border-zinc-200 shadow-inner">
                <div className="relative group/input">
                   <div className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-300 text-[10px] font-bold">R$</div>
                   <input 
                    type="number" 
                    placeholder="Novo gasto"
                    className="w-full p-4 pl-8 text-center text-sm outline-none bg-transparent focus:bg-yellow-50/50 font-black text-zinc-900 transition-all placeholder:text-zinc-300 placeholder:font-normal"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        handleValueEntry(col.linkedItemId, e.currentTarget.value);
                        e.currentTarget.value = '';
                      }
                    }}
                  />
                </div>
              </div>

              {/* Lista de Linhas (Corpo da Tabela) */}
              <div className="flex-grow flex flex-col bg-white border-x border-zinc-100 min-h-[350px]">
                {Array.from({ length: Math.max(12, partials.length) }).map((_, idx) => {
                  const p = partials[idx];
                  return (
                    <div key={idx} className={`border-b border-zinc-50 h-10 flex items-center justify-center relative group/row transition-colors ${p ? 'hover:bg-zinc-50' : ''}`}>
                      {p ? (
                        <div className="w-full flex justify-between items-center px-4 animate-in fade-in slide-in-from-left-2">
                          <span className="text-[9px] text-zinc-400 font-bold uppercase">{p.date}</span>
                          <span className="text-xs font-black text-zinc-800 font-mono tracking-tighter">{formatCurrency(p.value)}</span>
                          <button 
                            onClick={() => onRemovePartial(col.linkedItemId, p.id)}
                            className="opacity-0 group-hover/row:opacity-100 text-zinc-300 hover:text-red-500 transition-all p-1"
                          >
                            <i className="fas fa-times-circle"></i>
                          </button>
                        </div>
                      ) : (
                        <div className="w-full h-[1px] bg-zinc-50/50 mx-4"></div>
                      )}
                    </div>
                  );
                })}
              </div>

              {/* Rodapé (Totalizador) */}
              <div className={`p-5 rounded-b-2xl border border-zinc-200 text-center shadow-lg transition-all ${isOverLimit ? 'bg-red-50' : 'bg-zinc-900'}`}>
                <p className={`text-[9px] font-black uppercase mb-1 ${isOverLimit ? 'text-red-600' : 'text-zinc-500'}`}>Total Acumulado</p>
                <p className={`text-xl font-black font-mono tracking-tighter ${isOverLimit ? 'text-red-600' : 'text-yellow-500'}`}>
                  {formatCurrency(totalSpent)}
                </p>
                {teto > 0 && (
                   <div className="mt-2 w-full bg-zinc-800 h-1 rounded-full overflow-hidden">
                     <div 
                      className={`h-full transition-all duration-1000 ${isOverLimit ? 'bg-red-500' : 'bg-yellow-500'}`}
                      style={{ width: `${Math.min((totalSpent/teto)*100, 100)}%` }}
                     ></div>
                   </div>
                )}
              </div>

              {/* Botão de Excluir Coluna (Apenas no hover) */}
              <button 
                onClick={() => removeColumn(col.id)}
                className="absolute -top-3 -right-3 w-8 h-8 bg-zinc-900 text-zinc-500 hover:text-red-500 rounded-full border border-zinc-800 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all shadow-xl z-20"
              >
                <i className="fas fa-trash-alt text-xs"></i>
              </button>
            </div>
          );
        })}
      </div>

      {/* Card de Dica Inferior */}
      <div className="mt-12 bg-white rounded-[2rem] p-8 border border-zinc-100 shadow-xl flex flex-col md:flex-row items-center gap-8 relative overflow-hidden">
        <div className="absolute right-0 bottom-0 opacity-5 pointer-events-none">
          <i className="fas fa-gem text-[10rem] text-zinc-900"></i>
        </div>
        <div className="w-20 h-20 bg-zinc-900 rounded-2xl flex items-center justify-center shrink-0 shadow-2xl rotate-3">
          <i className="fas fa-chart-bar text-yellow-500 text-3xl"></i>
        </div>
        <div className="text-center md:text-left">
          <h4 className="font-black text-xl uppercase italic text-zinc-900 tracking-tight">Análise de Performance Semanal</h4>
          <p className="text-zinc-500 text-sm leading-relaxed mt-2 max-w-2xl">
            Esta aba foi desenhada para o seu **controle tático**. Enquanto a aba de 12 meses foca na sua estratégia, aqui você garante que o dia a dia não sabote o seu futuro. Lance cada cafezinho, cada ida ao mercado, e veja a barra de progresso. Mantenha-a amarela e sua liberdade financeira estará garantida.
          </p>
        </div>
      </div>
    </div>
  );
};

