        <button 
          onClick={() => onAddItem(category)}
          className="bg-yellow-600 hover:bg-yellow-400 text-black font-bold px-4 py-1.5 rounded-md transition-all shadow-lg flex items-center gap-2 text-sm"
        >
          <i className="fas fa-plus"></i> ADICIONAR
        </button>
      </div>

      <div className="overflow-x-auto">
        <style>{`
          input[type=number]::-webkit-inner-spin-button, 
          input[type=number]::-webkit-outer-spin-button { 
            -webkit-appearance: none; 
            margin: 0; 
          }
          input[type=number] {
            -moz-appearance: textfield;
          }
        `}</style>
        <table className="w-full text-sm text-left">
          <thead className="bg-gray-100 text-gray-700 uppercase font-semibold">
            <tr>
              <th className="p-4 border-b w-10"></th>
              <th className="p-4 border-b min-w-[220px]">Descrição</th>
              {months.map((m, idx) => (
                <th key={idx} className="p-4 border-b text-center min-w-[120px] border-l group relative">
                  {idx === 0 && onStartMonthChange && startMonth !== undefined ? (
                    <div className="flex items-center justify-center gap-1">
                      <select 
                        className="bg-transparent border-none focus:ring-0 text-center font-bold uppercase cursor-pointer hover:text-yellow-600 transition-colors p-0 appearance-none pr-4"
                        value={startMonth}
                        onChange={(e) => onStartMonthChange(parseInt(e.target.value))}
                      >
                        {MONTHS_BR.map((mName, i) => (
                          <option key={i} value={i}>{mName}</option>
                        ))}
                      </select>
                      <i className="fas fa-chevron-down text-[10px] absolute right-2 pointer-events-none text-gray-400"></i>
                    </div>
                  ) : (
                    m.monthName
                  )}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {items.map((item) => (
              <tr key={item.id} className="border-b hover:bg-gray-50 transition-colors">
                <td className="p-2 text-center">
                  <button 
                    onClick={() => onRemoveItem(item.id)}
                    className="text-gray-300 hover:text-red-500 transition-colors p-2"
                    title="Excluir linha"
                  >
                    <i className="fas fa-trash-alt text-xs"></i>
                  </button>
                </td>
                <td className="p-2">
                  <div className="flex flex-col gap-1">
                    <input
                      type="text"
                      value={item.description}
                      onChange={(e) => onUpdateDescription(item.id, e.target.value)}
                      className="w-full bg-transparent border-b border-transparent focus:border-yellow-500 outline-none p-2 text-gray-900 font-medium"
                      placeholder="Nome do item..."
                    />
                    {showLinkOption && onLinkCard && (
                      <div className="px-2 pb-1 flex flex-col gap-1">
                        <div className="flex items-center gap-2">
                          <i className="fas fa-credit-card text-[10px] text-gray-400"></i>
                          <select 
                            className="text-[10px] bg-transparent border-none text-gray-500 focus:ring-0 cursor-pointer hover:text-yellow-600 transition-colors p-0"
                            value={item.linkedCardId || ''}
                            onChange={(e) => onLinkCard(item.id, e.target.value, item.linkType || LinkType.RECURRING)}
                          >
                            <option value="">Dinheiro/Débito</option>
                            {allCards.map(card => (
                              <option key={card.id} value={card.id}>Cartão: {card.description || 'S/N'}</option>
                            ))}
                          </select>
                        </div>
                        {item.linkedCardId && (
                          <div className="flex items-center gap-2 ml-4">
                            <select 
                              className="text-[9px] bg-zinc-100 rounded px-1 text-zinc-600 font-bold border-none focus:ring-0 cursor-pointer"
                              value={item.linkType || LinkType.RECURRING}
                              onChange={(e) => onLinkCard(item.id, item.linkedCardId!, e.target.value as LinkType)}
                            >
                              <option value={LinkType.RECURRING}>Mês a mês</option>
                              <option value={LinkType.INSTALLMENT}>Já na fatura</option>
                            </select>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </td>
                {item.values.map((val, mIdx) => {
                  const isPaid = item.paidStatus[mIdx];
                  const isIncome = category === CategoryType.INCOME;

                  // Calcular o realizado (somente para o mês atual, que é mIdx 0 no planejamento)
                  const monthData = months[mIdx];
                  const monthKey = `${monthData.year}-${monthData.index}`;
                  const partials = item.partialExpenses?.[monthKey] || [];
                  const realSpent = partials.reduce((acc, p) => acc + p.value, 0);
                  const isOver = realSpent > val && val > 0;

                  return (
                    <td key={mIdx} className={`p-2 border-l text-center transition-all ${isPaid ? 'bg-green-50/30' : ''}`}>
                      <div className="flex flex-col gap-1.5 items-center">
                        <div className="relative w-full group">
                          <input
                            type="number"
                            step="0.01"
                            value={val === 0 ? '' : val}
                            onChange={(e) => onUpdateValue(item.id, mIdx, e.target.value)}
                            className={`w-full text-center bg-transparent border-none focus:ring-0 outline-none transition-all text-sm ${
                              isPaid ? 'text-green-700 font-bold' : 'text-gray-900'
                            }`}
                            placeholder="0,00"
                          />
                          <button
                            onClick={() => onReplicateValue(item.id, mIdx)}
                            title="Replicar valores"
                            className="absolute -right-1 -top-1 opacity-0 group-hover:opacity-100 bg-yellow-500 text-black w-4 h-4 rounded-full flex items-center justify-center text-[8px] shadow-sm transition-opacity hover:scale-110"
                          >
                            <i className="fas fa-sync-alt"></i>
                          </button>
                        </div>

                        {/* Indicador de Realizado (Sync com a aba de Lançamentos) */}
                        {realSpent > 0 && (
                          <div className={`text-[9px] font-black px-1.5 py-0.5 rounded uppercase flex items-center gap-1 ${isOver ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                            <i className="fas fa-check-double text-[8px]"></i>
                            Realizado: {formatCurrency(realSpent)}
                          </div>
                        )}

                        {!isIncome && (
                          <button
                            onClick={() => onTogglePaid(item.id, mIdx)}
                            className={`w-3 h-3 rounded-full border-2 transition-all duration-300 ${
                              isPaid 
                                ? 'bg-green-500 border-green-500 shadow-[0_0_5px_rgba(34,197,94,0.5)]' 
                                : 'bg-transparent border-gray-300 hover:border-green-400'
                            }`}
                            title={isPaid ? "Pago" : "Pendente"}
                          />
                        )}
                      </div>
                    </td>
                  );
                })}
              </tr>
            ))}
            {items.length === 0 && (
              <tr>
                <td colSpan={months.length + 2} className="p-8 text-center text-gray-400 italic">
                  Nenhum item adicionado.
                </td>
              </tr>
            )}
          </tbody>
          <tfoot className="bg-gray-50 font-bold border-t border-gray-200">
            <tr>
              <td className="p-4"></td>
              <td className="p-4 text-gray-500 text-xs uppercase tracking-tighter">Subtotal</td>
              {months.map((_, mIdx) => {
                const total = items.reduce((acc, item) => acc + (item.values[mIdx] || 0), 0);
                return (
                  <td key={mIdx} className="p-4 text-center border-l border-gray-200 text-zinc-900">
                    {formatCurrency(total)}
                  </td>
                );
              })}
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

export default BlockSection;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { SummaryData, FinanceItem, CategoryType } from '../types';
import { IDEAL_LIMITS, formatCurrency } from '../constants';

interface AICoachProps {
  summary: SummaryData;
  items: FinanceItem[];
  monthName: string;
}

const AICoach: React.FC<AICoachProps> = ({ summary, items, monthName }) => {
  const [prompt, setPrompt] = useState('');
  const [response, setResponse] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const analyzeFinance = async () => {
    setLoading(true);
    setResponse(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Preparar contexto para a IA
    const fixedPercent = (summary.totalFixed / summary.totalIncome) * 100;
    const leisurePercent = (summary.totalLeisure / summary.totalIncome) * 100;
    const creditCardPercent = (summary.totalCreditCard / summary.totalIncome) * 100;

    const context = `
      Você é um mentor financeiro sênior do método "RICO nessa vida".
      Dados atuais do mês de ${monthName}:
      - Renda Total: ${formatCurrency(summary.totalIncome)}
      - Gastos Fixos: ${formatCurrency(summary.totalFixed)} (${fixedPercent.toFixed(1)}% da renda. Ideal: até 55%)
      - Lazer/Pessoal: ${formatCurrency(summary.totalLeisure)} (${leisurePercent.toFixed(1)}% da renda. Ideal: até 15%)
      - Faturas de Cartão: ${formatCurrency(summary.totalCreditCard)} (${creditCardPercent.toFixed(1)}% da renda)
      - Saldo que sobra: ${formatCurrency(summary.balance)}
      - Acumulado planejado em 12 meses: ${formatCurrency(summary.accumulated)}

      Instruções:
      1. Seja direto, prático e motivador, mas firme quando houver erros.
      2. Se os gastos fixos passarem de 55%, aponte isso como o principal ralo financeiro.
      3. Se o lazer passar de 15%, fale sobre disciplina.
      4. Se o saldo for negativo, dê um alerta de urgência.
      5. Use Markdown para formatar a resposta com tópicos e negrito.
    `;

    try {
      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt || "De acordo com a minha vida financeira, onde está o principal erro?",
        config: {
          systemInstruction: context,
          thinkingConfig: { thinkingBudget: 0 }
        }
      });
      setResponse(result.text);
    } catch (error) {
      setResponse("Desculpe, tive um problema ao analisar seus dados. Tente novamente em instantes.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-[#0a0a0a] border border-zinc-800 rounded-3xl p-6 mb-8 shadow-2xl relative overflow-hidden group">
      <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform">
        <i className="fas fa-robot text-8xl text-yellow-500"></i>
      </div>

      <div className="relative z-10">
        <div className="flex items-center gap-3 mb-4">
          <div className="w-10 h-10 bg-yellow-500 rounded-full flex items-center justify-center animate-pulse">
            <i className="fas fa-brain text-black"></i>
          </div>
          <h3 className="text-white font-black text-xl uppercase italic tracking-tighter">Mentor IA - Diagnóstico Estratégico</h3>
        </div>

        <div className="flex flex-col gap-4">
          <div className="flex gap-2">
            <input 
              type="text" 
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="Ex: Onde está o meu principal erro financeiro hoje?"
              className="flex-grow bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 text-white text-sm outline-none focus:border-yellow-500 transition-all"
            />
            <button 
              onClick={analyzeFinance}
              disabled={loading}
              className="bg-yellow-600 hover:bg-yellow-500 text-black font-black px-6 py-3 rounded-xl text-xs uppercase transition-all disabled:opacity-50"
            >
              {loading ? <i className="fas fa-spinner animate-spin"></i> : 'Analisar'}
            </button>
          </div>

          {response && (
            <div className="mt-4 bg-zinc-900/50 border border-zinc-800 p-6 rounded-2xl text-zinc-300 text-sm leading-relaxed animate-in slide-in-from-top-2">
              <div className="prose prose-invert max-w-none">
                {response.split('\n').map((line, i) => (
                  <p key={i} className="mb-2">{line}</p>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AICoach;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { CategoryType, FinanceItem, SummaryData, LinkType, PartialExpense } from './types';
import { getNext12Months, formatCurrency, MONTHS_BR } from './constants';
import BlockSection from './components/BlockSection';
import Diagnosis from './components/Diagnosis';
import TetoGastos from './components/TetoGastos';
import AICoach from './components/AICoach';

const DEFAULT_FIXED_EXPENSES = [
  'Moradia', 'Condominio', 'Telefone fixo', 'Internet', 'Celular',
  'Compras mercado (média mensal)', 'Gás', 'Luz', 'Água', 'Convênio',
  'Gasolina/uber (media mensal)', 'Iptu (mensal)', 'Educação',
  'Unha e sobrancelha', 'Academia', 'Cabelo', 'Estética', 'Dízimo',
  'Diarista', 'Comida pet', 'Banho pet', 'Personal', 'Netflix', 'Spotify',
  'Emprestimo (parcela mensal)', 'Previdência', 'Parcela seguro carro',
  'Parcela de carro', 'Terapia', 'Emprestimo'
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'plan' | 'teto'>('plan');
  const [startMonth, setStartMonth] = useState<number>(() => {
    const saved = localStorage.getItem('finance_start_month');
    return saved ? parseInt(saved) : new Date().getMonth();
  });

  const months = useMemo(() => getNext12Months(startMonth), [startMonth]);
  const currentActualMonth = new Date().getMonth();
  const currentActualYear = new Date().getFullYear();

  const [items, setItems] = useState<FinanceItem[]>(() => {
    const saved = localStorage.getItem('finance_data');
    if (saved) return JSON.parse(saved);

    return DEFAULT_FIXED_EXPENSES.map((desc, idx) => ({
      id: `default-fixed-${idx}`,
      description: desc,
      category: CategoryType.FIXED_EXPENSE,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    }));
  });

  useEffect(() => { localStorage.setItem('finance_data', JSON.stringify(items)); }, [items]);
  useEffect(() => { localStorage.setItem('finance_start_month', startMonth.toString()); }, [startMonth]);

  const handleAddItem = (category: CategoryType) => {
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: category === CategoryType.PERSONAL_LEISURE ? 'Lazer e Gastos Pessoais' : '', 
      category,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    };
    setItems(prev => [...prev, newItem]);
  };

  const handleUpdateValue = (id: string, monthIdx: number, value: string) => {
    const numericValue = value === '' ? 0 : parseFloat(value);
    setItems(prev => prev.map(item => item.id === id ? { ...item, values: item.values.map((v, i) => i === monthIdx ? numericValue : v) } : item));
  };

  const handleUpdateDescription = (id: string, desc: string) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, description: desc } : item));
  };

  const handleTogglePaid = (id: string, monthIdx: number) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, paidStatus: item.paidStatus.map((s, i) => i === monthIdx ? !s : s) } : item));
  };

  const handleRemoveItem = (id: string) => {
    setItems(prev => prev.filter(item => item.id !== id));
  };

  const handleAddPartial = (itemId: string, expense: PartialExpense) => {
    const monthKey = `${currentActualYear}-${currentActualMonth}`;
    setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const partials = item.partialExpenses || {};
      const monthPartials = partials[monthKey] || [];
      return { ...item, partialExpenses: { ...partials, [monthKey]: [...monthPartials, expense] } };
    }));
  };

  const handleRemovePartial = (itemId: string, expenseId: string) => {
    const monthKey = `${currentActualYear}-${currentActualMonth}`;
    setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const partials = item.partialExpenses || {};
      const monthPartials = partials[monthKey] || [];
      return { ...item, partialExpenses: { ...partials, [monthKey]: monthPartials.filter(p => p.id !== expenseId) } };
    }));
  };

  const handleReplicateValue = (id: string, monthIdx: number) => {
    setItems(prev => prev.map(i => i.id === id ? { ...i, values: i.values.map((v, idx) => idx >= monthIdx ? i.values[monthIdx] : v) } : i));
  };

  const handleLinkCard = (itemId: string, cardId: string, linkType?: LinkType) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, linkedCardId: cardId || undefined, linkType: cardId ? (linkType || LinkType.RECURRING) : undefined } : item));
  };

  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;
    for (let m = 0; m < 12; m++) {
      const totalIncome = items.filter(i => i.category === CategoryType.INCOME).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCreditCardBruto = items.filter(i => i.category === CategoryType.CREDIT_CARD).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixed = items.filter(i => i.category === CategoryType.FIXED_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixedDuplicado = items.filter(i => i.category === CategoryType.FIXED_EXPENSE && i.linkedCardId && (m === 0 || i.linkType === LinkType.INSTALLMENT)).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariable = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariableDuplicado = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE && i.linkedCardId && (m === 0 || i.linkType === LinkType.INSTALLMENT)).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalLeisure = items.filter(i => i.category === CategoryType.PERSONAL_LEISURE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCost = totalCreditCardBruto + (totalFixed - totalFixedDuplicado) + (totalVariable - totalVariableDuplicado) + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;
      summaries.push({ totalIncome, totalCreditCard: totalCreditCardBruto, totalFixed, totalVariable, totalLeisure, totalCost, balance, accumulated });
    }
    return summaries;
  }, [items]);

  const allCards = useMemo(() => items.filter(i => i.category === CategoryType.CREDIT_CARD), [items]);

  return (
    <div className="min-h-screen pb-20 bg-gray-50 text-gray-900">
      <header className="bg-[#0f0f0f] text-white py-4 px-8 shadow-2xl mb-8 sticky top-0 z-50 border-b-2 border-yellow-600/50">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-6">
            <span className="text-3xl font-black italic bg-clip-text text-transparent bg-gradient-to-b from-yellow-200 to-yellow-700 uppercase tracking-tighter">RICO nessa vida</span>
          </div>
          <div className="flex gap-2 bg-zinc-900 p-1 rounded-xl border border-zinc-800">
            <button 
              onClick={() => setActiveTab('plan')}
              className={`px-4 md:px-6 py-2 rounded-lg text-[10px] md:text-xs font-black uppercase transition-all ${activeTab === 'plan' ? 'bg-yellow-600 text-black shadow-lg shadow-yellow-600/20' : 'text-gray-400 hover:text-white'}`}
            >
              <i className="fas fa-calendar-alt mr-2"></i> 12 Meses
            </button>
            <button 
              onClick={() => setActiveTab('teto')}
              className={`px-4 md:px-6 py-2 rounded-lg text-[10px] md:text-xs font-black uppercase transition-all ${activeTab === 'teto' ? 'bg-yellow-600 text-black shadow-lg shadow-yellow-600/20' : 'text-gray-400 hover:text-white'}`}
            >
              <i className="fas fa-table mr-2"></i> Lançamentos (Teto)
            </button>
          </div>
        </div>
      </header>

      <main className={`${activeTab === 'plan' ? 'max-w-[1600px]' : 'w-full px-2'} mx-auto px-4 md:px-8`}>
        {activeTab === 'plan' ? (
          <>
            <AICoach 
              summary={monthlySummaries[0]} 
              items={items} 
              monthName={months[0].monthName} 
            />
            <Diagnosis summary={monthlySummaries[0]} monthName={months[0].monthName} />
            {[
              { title: "ENTRADAS (Rendas)", type: CategoryType.INCOME },
              { title: "FATURAS DE CARTÃO", type: CategoryType.CREDIT_CARD },
              { title: "CONTAS FIXAS", subtitle: "Recorrentes, Regulares ou > 18 parcelas", type: CategoryType.FIXED_EXPENSE },
              { title: "CONTAS VARIÁVEIS", type: CategoryType.VARIABLE_EXPENSE },
              { title: "LAZER E GASTOS PESSOAIS", type: CategoryType.PERSONAL_LEISURE }
            ].map(block => (
              <BlockSection 
                key={block.type} title={block.title} subtitle={block.subtitle} category={block.type} 
                items={items.filter(i => i.category === block.type)} allCards={allCards}
                months={months} startMonth={startMonth} onStartMonthChange={setStartMonth}
                onAddItem={handleAddItem} onUpdateValue={handleUpdateValue} onTogglePaid={handleTogglePaid} 
                onRemoveItem={handleRemoveItem} onUpdateDescription={handleUpdateDescription} 
                onReplicateValue={handleReplicateValue} onLinkCard={handleLinkCard}
              />
            ))}
          </>
        ) : (
          <TetoGastos 
            items={items} 
            currentMonthIdx={currentActualMonth} 
            currentYear={currentActualYear}
            onAddPartial={handleAddPartial}
            onRemovePartial={handleRemovePartial}
          />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { SummaryData, FinanceItem, CategoryType, PartialExpense } from '../types';
import { IDEAL_LIMITS, formatCurrency } from '../constants';

interface AICoachProps {
  summary: SummaryData;
  items: FinanceItem[];
  monthName: string;
  onAddPartial: (itemId: string, expense: PartialExpense) => void;
}

const AICoach: React.FC<AICoachProps> = ({ summary, items, monthName, onAddPartial }) => {
  const [prompt, setPrompt] = useState('');
  const [response, setResponse] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const analyzeOrAction = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setResponse(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const fixedPercent = (summary.totalFixed / summary.totalIncome) * 100;
    const leisurePercent = (summary.totalLeisure / summary.totalIncome) * 100;
    const creditCardPercent = (summary.totalCreditCard / summary.totalIncome) * 100;

    // Lista de itens disponíveis para lançamento (apenas os que têm descrição)
    const availableItems = items
      .filter(i => i.category !== CategoryType.INCOME)
      .map(i => ({ id: i.id, description: i.description }));

    const systemInstruction = `
      Você é o assistente do método "RICO nessa vida".
      Sua missão é:
      1. ANALISAR: Se o usuário perguntar sobre a vida financeira, use os dados: Renda ${formatCurrency(summary.totalIncome)}, Fixos ${fixedPercent.toFixed(1)}% (ideal 55%), Lazer ${leisurePercent.toFixed(1)}% (ideal 15%).
      2. LANÇAR GASTOS: Se o usuário disser que gastou algo (ex: "gastei 50 no mercado"), você deve identificar o VALOR e a CATEGORIA mais provável entre: ${JSON.stringify(availableItems)}.

      IMPORTANTE: Para lançamentos, use a função 'registrar_gasto'.
      Se não for um lançamento, responda normalmente em Markdown.
    `;

    const registrarGastoTool = {
      name: 'registrar_gasto',
      parameters: {
        type: Type.OBJECT,
        description: 'Registra um novo gasto nas planilhas de lançamento',
        properties: {
          itemId: { type: Type.STRING, description: 'O ID do item/coluna correspondente' },
          valor: { type: Type.NUMBER, description: 'O valor numérico do gasto' },
