  onComplete: () => void;
}

const steps: TutorialStep[] = [
  {
    target: 'header',
    title: 'Bem-vindo ao seu novo estilo de vida!',
    content: 'Este é o "RICO nessa vida". Aqui, a organização é o seu primeiro passo para a liberdade financeira.',
    icon: 'fa-rocket'
  },
  {
    target: 'stets',
    title: 'Conheça o Stets',
    content: 'O Stets é seu professor digital. Você pode falar com ele por voz ou texto para lançar gastos rapidamente ou pedir um diagnóstico.',
