    icon: 'fa-rocket'
  },
  {
    target: 'stets',
    title: 'Conheça o Stets',
    content: 'O Stets é seu professor digital. Fale com ele por voz ou texto para lançar gastos rapidamente ou pedir um diagnóstico de saúde financeira.',
    icon: 'fa-brain'
  },
  {
    target: 'replicate-info',
    title: 'Ganhe Tempo com um Clique',
    content: 'Reparou no botão amarelo circular ao lado dos valores? Ele replica o valor atual para todos os meses seguintes automaticamente. Ideal para aluguel, internet e parcelas fixas!',
    icon: 'fa-sync-alt'
  },
  {
    target: 'tab-launcamentos',
    title: 'Aba de Lançamentos (Teto)',
    content: 'É aqui que a mágica acontece no dia a dia. Você define um "Teto" e lança cada gasto pequeno. O sistema te avisa se você está chegando no limite planejado antes do mês acabar.',
    icon: 'fa-table'
  },
  {
    target: 'summary-section',
    title: 'Resumo e Acumulado',
    content: 'No final da página, você tem a bússola do seu enriquecimento: Total de custos, saldo mensal e o ACUMULADO. Descubra exatamente quanto dinheiro terá daqui a 12 meses se seguir o plano.',
    icon: 'fa-vault'
  }
];

const OnboardingTutorial: React.FC<OnboardingTutorialProps> = ({ onComplete }) => {
  const [currentStep, setCurrentStep] = useState(0);

  const nextStep = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      onComplete();
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/85 backdrop-blur-md animate-in fade-in duration-500">
      <div className="max-w-md w-full bg-zinc-900 border border-zinc-800 rounded-[40px] p-8 shadow-2xl relative overflow-hidden">
        {/* Progress Bar */}
        <div className="absolute top-0 left-0 w-full h-1 bg-zinc-800">
          <div 
            className="h-full bg-yellow-500 transition-all duration-500" 
            style={{ width: `${((currentStep + 1) / steps.length) * 100}%` }}
          ></div>
        </div>

        <div className="text-center mt-4">
          <div className="w-20 h-20 bg-yellow-500/10 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-yellow-500/20">
            <i className={`fas ${steps[currentStep].icon} text-4xl text-yellow-500`}></i>
          </div>

          <h3 className="text-white text-2xl font-black italic uppercase tracking-tighter mb-4 leading-tight">
            {steps[currentStep].title}
          </h3>

          <p className="text-zinc-400 text-sm leading-relaxed mb-10 px-2">
            {steps[currentStep].content}
          </p>

          <div className="flex flex-col gap-3">
            <button 
              onClick={nextStep}
              className="w-full bg-yellow-600 hover:bg-yellow-500 text-black font-black py-4 rounded-2xl transition-all active:scale-95 shadow-lg uppercase text-xs tracking-widest"
            >
              {currentStep === steps.length - 1 ? 'Entendido, vamos lá!' : 'Próximo Passo'}
            </button>

            <button 
              onClick={onComplete}
              className="text-zinc-500 hover:text-white text-[10px] font-bold uppercase tracking-[0.2em] transition-colors py-2"
            >
              Pular tutorial
            </button>
          </div>
        </div>

        <div className="mt-10 flex justify-center gap-2">
          {steps.map((_, idx) => (
            <div 
              key={idx} 
              className={`h-1 rounded-full transition-all ${idx === currentStep ? 'w-8 bg-yellow-500' : 'w-2 bg-zinc-800'}`}
            ></div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default OnboardingTutorial;

import React, { useState, useEffect, useMemo } from 'react';
import { CategoryType, FinanceItem, SummaryData, LinkType, PartialExpense } from './types';
import { getNext12Months, formatCurrency } from './constants';
import BlockSection from './components/BlockSection';
import Diagnosis from './components/Diagnosis';
import TetoGastos from './components/TetoGastos';
import AICoach from './components/AICoach';
import OnboardingTutorial from './components/OnboardingTutorial';

const DEFAULT_FIXED_EXPENSES = [
  'Moradia', 'Condominio', 'Telefone fixo', 'Internet', 'Celular',
  'Compras mercado (média mensal)', 'Gás', 'Luz', 'Água', 'Convênio',
  'Gasolina/uber (media mensal)', 'Iptu (mensal)', 'Educação',
  'Unha e sobrancelha', 'Academia', 'Cabelo', 'Estética', 'Dízimo',
  'Diarista', 'Comida pet', 'Banho pet', 'Personal', 'Netflix', 'Spotify',
  'Emprestimo (parcela mensal)', 'Previdência', 'Parcela seguro carro',
  'Parcela de carro', 'Terapia', 'Emprestimo'
];

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return localStorage.getItem('finance_auth') === 'true';
  });
  const [showTutorial, setShowTutorial] = useState<boolean>(() => {
    return localStorage.getItem('tutorial_completed') !== 'true';
  });
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [userProfile, setUserProfile] = useState<{name: string, photo?: string} | null>(null);

  const [formData, setFormData] = useState({ name: '', email: '', password: '', confirmPassword: '' });

  const [activeTab, setActiveTab] = useState<'plan' | 'teto'>('plan');
  const [startMonth, setStartMonth] = useState<number>(() => {
    const saved = localStorage.getItem('finance_start_month');
    return saved ? parseInt(saved) : new Date().getMonth();
  });

  const months = useMemo(() => getNext12Months(startMonth), [startMonth]);
  const currentActualMonth = new Date().getMonth();
  const currentActualYear = new Date().getFullYear();

  const [items, setItems] = useState<FinanceItem[]>(() => {
    const saved = localStorage.getItem('finance_data');
    if (saved) return JSON.parse(saved);

    return DEFAULT_FIXED_EXPENSES.map((desc, idx) => ({
      id: `default-fixed-${idx}`,
      description: desc,
      category: CategoryType.FIXED_EXPENSE,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    }));
  });

  useEffect(() => { localStorage.setItem('finance_data', JSON.stringify(items)); }, [items]);
  useEffect(() => { localStorage.setItem('finance_start_month', startMonth.toString()); }, [startMonth]);
  useEffect(() => { localStorage.setItem('finance_auth', isAuthenticated.toString()); }, [isAuthenticated]);

  const handleSocialLogin = (provider: 'google' | 'facebook') => {
    setIsAuthenticated(true);
    setUserProfile({
      name: provider === 'google' ? 'Usuário Google' : 'Usuário Facebook',
      photo: provider === 'google' ? 'https://cdn-icons-png.flaticon.com/512/2991/2991148.png' : 'https://cdn-icons-png.flaticon.com/512/124/124010.png'
    });
  };

  const handleManualAuth = (e: React.FormEvent) => {
    e.preventDefault();
    if (authMode === 'register' && formData.password !== formData.confirmPassword) {
      alert("As senhas não coincidem!");
      return;
    }
    setIsAuthenticated(true);
    setUserProfile({ name: formData.name || formData.email.split('@')[0], photo: 'https://cdn-icons-png.flaticon.com/512/149/149071.png' });
  };

  const handleCompleteTutorial = () => {
    setShowTutorial(false);
    localStorage.setItem('tutorial_completed', 'true');
  };

  const handleAddItem = (category: CategoryType) => {
    const newItem: FinanceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: category === CategoryType.PERSONAL_LEISURE ? 'Lazer e Gastos Pessoais' : '', 
      category,
      values: new Array(12).fill(0),
      paidStatus: new Array(12).fill(false)
    };
    setItems(prev => [...prev, newItem]);
  };

  const handleUpdateValue = (id: string, monthIdx: number, value: string) => {
    const numericValue = value === '' ? 0 : parseFloat(value);
    setItems(prev => prev.map(item => item.id === id ? { ...item, values: item.values.map((v, i) => i === monthIdx ? numericValue : v) } : item));
  };

  const handleUpdateDescription = (id: string, desc: string) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, description: desc } : item));
  };

  const handleTogglePaid = (id: string, monthIdx: number) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, paidStatus: item.paidStatus.map((s, i) => i === monthIdx ? !s : s) } : item));
  };

  const handleRemoveItem = (id: string) => {
    setItems(prev => prev.filter(item => item.id !== id));
  };

  const handleAddPartial = (itemId: string, expense: PartialExpense) => {
    const monthKey = `${currentActualYear}-${currentActualMonth}`;
    setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const partials = item.partialExpenses || {};
      const monthPartials = partials[monthKey] || [];
      return { ...item, partialExpenses: { ...partials, [monthKey]: [...monthPartials, expense] } };
    }));
  };

  const handleRemovePartial = (itemId: string, expenseId: string) => {
    const monthKey = `${currentActualYear}-${currentActualMonth}`;
    setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const partials = item.partialExpenses || {};
      const monthPartials = partials[monthKey] || [];
      return { ...item, partialExpenses: { ...partials, [monthKey]: monthPartials.filter(p => p.id !== expenseId) } };
    }));
  };

  const handleReplicateValue = (id: string, monthIdx: number) => {
    setItems(prev => prev.map(i => i.id === id ? { ...i, values: i.values.map((v, idx) => idx >= monthIdx ? i.values[monthIdx] : v) } : i));
  };

  const handleLinkCard = (itemId: string, cardId: string, linkType?: LinkType) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, linkedCardId: cardId || undefined, linkType: cardId ? (linkType || LinkType.RECURRING) : undefined } : item));
  };

  const monthlySummaries = useMemo((): SummaryData[] => {
    const summaries: SummaryData[] = [];
    let accumulated = 0;
    for (let m = 0; m < 12; m++) {
      const totalIncome = items.filter(i => i.category === CategoryType.INCOME).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCreditCardBruto = items.filter(i => i.category === CategoryType.CREDIT_CARD).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixed = items.filter(i => i.category === CategoryType.FIXED_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalFixedDuplicado = items.filter(i => i.category === CategoryType.FIXED_EXPENSE && i.linkedCardId && (m === 0 || i.linkType === LinkType.INSTALLMENT)).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariable = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalVariableDuplicado = items.filter(i => i.category === CategoryType.VARIABLE_EXPENSE && i.linkedCardId && (m === 0 || i.linkType === LinkType.INSTALLMENT)).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalLeisure = items.filter(i => i.category === CategoryType.PERSONAL_LEISURE).reduce((sum, i) => sum + (i.values[m] || 0), 0);
      const totalCost = totalCreditCardBruto + (totalFixed - totalFixedDuplicado) + (totalVariable - totalVariableDuplicado) + totalLeisure;
      const balance = totalIncome - totalCost;
      accumulated += balance;
      summaries.push({ totalIncome, totalCreditCard: totalCreditCardBruto, totalFixed, totalVariable, totalLeisure, totalCost, balance, accumulated });
    }
    return summaries;
  }, [items]);

  const allCards = useMemo(() => items.filter(i => i.category === CategoryType.CREDIT_CARD), [items]);

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-[#050505] flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-yellow-600/10 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-yellow-600/5 rounded-full blur-[120px]"></div>

        <div className="max-w-md w-full relative z-10 text-center">
          <div className="mb-10">
            <h1 className="text-5xl font-black italic bg-clip-text text-transparent bg-gradient-to-b from-yellow-100 to-yellow-600 uppercase tracking-tighter leading-none mb-4">
              RICO nessa vida
            </h1>
            <p className="text-zinc-400 text-sm font-medium tracking-wide italic">A forma mais simples de se organizar financeiramente está aqui.</p>
          </div>

          <div className="bg-zinc-900/50 border border-zinc-800 p-8 rounded-[40px] backdrop-blur-xl shadow-2xl transition-all duration-500">
            <h2 className="text-white font-bold text-xl mb-8 uppercase tracking-widest italic">
              {authMode === 'login' ? 'Acesse sua conta' : 'Crie sua conta premium'}
            </h2>

            <form onSubmit={handleManualAuth} className="flex flex-col gap-4 mb-8">
              {authMode === 'register' && (
                <div className="relative">
                  <input 
                    type="text" 
                    required
                    placeholder="Seu nome completo"
                    className="w-full bg-zinc-950 border border-zinc-800 rounded-2xl px-5 py-3.5 text-white text-sm outline-none focus:border-yellow-600 transition-all shadow-inner"
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                  />
                </div>
              )}
              <div className="relative">
                <input 
                  type="email" 
                  required
                  placeholder="Seu melhor e-mail"
                  className="w-full bg-zinc-950 border border-zinc-800 rounded-2xl px-5 py-3.5 text-white text-sm outline-none focus:border-yellow-600 transition-all shadow-inner"
                  value={formData.email}
                  onChange={(e) => setFormData({...formData, email: e.target.value})}
                />
              </div>
              <div className="relative">
                <input 
                  type="password" 
                  required
                  placeholder="Sua senha secreta"
                  className="w-full bg-zinc-950 border border-zinc-800 rounded-2xl px-5 py-3.5 text-white text-sm outline-none focus:border-yellow-600 transition-all shadow-inner"
                  value={formData.password}
                  onChange={(e) => setFormData({...formData, password: e.target.value})}
                />
              </div>
              {authMode === 'register' && (
                <div className="relative">
                  <input 
                    type="password" 
                    required
                    placeholder="Confirme sua senha"
                    className="w-full bg-zinc-950 border border-zinc-800 rounded-2xl px-5 py-3.5 text-white text-sm outline-none focus:border-yellow-600 transition-all shadow-inner"
                    value={formData.confirmPassword}
                    onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})}
                  />
                </div>
              )}

              <button 
                type="submit"
                className="bg-yellow-600 hover:bg-yellow-500 text-black font-black py-4 px-6 rounded-2xl transition-all active:scale-95 shadow-lg uppercase text-xs tracking-widest mt-2"
              >
                {authMode === 'login' ? 'Entrar Agora' : 'Finalizar Registro'}
              </button>
            </form>

            <div className="relative flex items-center justify-center mb-8">
              <span className="w-full h-[1px] bg-zinc-800"></span>
              <span className="absolute bg-[#0a0a0a] px-4 text-[10px] text-zinc-600 font-black uppercase tracking-[0.2em]">ou use social</span>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <button 
                onClick={() => handleSocialLogin('google')}
                className="flex items-center justify-center gap-3 bg-zinc-950 border border-zinc-800 hover:border-zinc-700 text-white font-bold py-3.5 px-4 rounded-2xl transition-all active:scale-95 group"
              >
                <i className="fab fa-google text-lg text-[#DB4437]"></i>
                <span className="text-[10px] uppercase tracking-tighter">Google</span>
              </button>

              <button 
                onClick={() => handleSocialLogin('facebook')}
                className="flex items-center justify-center gap-3 bg-zinc-950 border border-zinc-800 hover:border-zinc-700 text-white font-bold py-3.5 px-4 rounded-2xl transition-all active:scale-95 group"
              >
                <i className="fab fa-facebook text-xl text-[#1877F2]"></i>
                <span className="text-[10px] uppercase tracking-tighter">Facebook</span>
              </button>
            </div>

            <button 
              onClick={() => setAuthMode(authMode === 'login' ? 'register' : 'login')}
              className="text-zinc-500 hover:text-yellow-500 text-[11px] font-bold uppercase tracking-widest mt-10 transition-colors"
            >
              {authMode === 'login' ? 'Não tem uma conta? Registre-se aqui' : 'Já possui conta? Faça o login'}
            </button>
          </div>

          <div className="mt-10 text-zinc-600 text-[10px] font-bold uppercase tracking-[0.3em] flex items-center justify-center gap-4">
            <span className="w-8 h-[1px] bg-zinc-800"></span>
            Professor Digital Stets
            <span className="w-8 h-[1px] bg-zinc-800"></span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20 bg-gray-50 text-gray-900">
      {showTutorial && <OnboardingTutorial onComplete={handleCompleteTutorial} />}

      <header id="header" className="bg-[#0f0f0f] text-white py-4 px-8 shadow-2xl mb-8 sticky top-0 z-50 border-b-2 border-yellow-600/50">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-6">
            <span className="text-3xl font-black italic bg-clip-text text-transparent bg-gradient-to-b from-yellow-200 to-yellow-700 uppercase tracking-tighter">RICO nessa vida</span>
            {userProfile && (
               <div className="hidden md:flex items-center gap-3 border-l border-zinc-800 pl-6">
                  <img src={userProfile.photo} className="w-8 h-8 rounded-full border border-yellow-500/30" alt="Profile" />
                  <span className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Bem-vindo, {userProfile.name.split(' ')[0]}</span>
               </div>
            )}
          </div>
          <div className="flex gap-2 bg-zinc-900 p-1 rounded-xl border border-zinc-800">
            <button 
              onClick={() => setActiveTab('plan')}
              className={`px-4 md:px-6 py-2 rounded-lg text-[10px] md:text-xs font-black uppercase transition-all ${activeTab === 'plan' ? 'bg-yellow-600 text-black shadow-lg shadow-yellow-600/20' : 'text-gray-400 hover:text-white'}`}
            >
              <i className="fas fa-calendar-alt mr-2"></i> 12 Meses
            </button>
            <button 
              id="tab-launcamentos"
              onClick={() => setActiveTab('teto')}
              className={`px-4 md:px-6 py-2 rounded-lg text-[10px] md:text-xs font-black uppercase transition-all ${activeTab === 'teto' ? 'bg-yellow-600 text-black shadow-lg shadow-yellow-600/20' : 'text-gray-400 hover:text-white'}`}
            >
              <i className="fas fa-table mr-2"></i> Lançamentos (Teto)
            </button>
            <button 
              onClick={() => { setIsAuthenticated(false); localStorage.removeItem('finance_auth'); }}
              className="px-3 py-2 text-zinc-600 hover:text-red-500 transition-colors"
              title="Sair"
            >
              <i className="fas fa-sign-out-alt"></i>
            </button>
          </div>
        </div>
      </header>

      <main className={`${activeTab === 'plan' ? 'max-w-[1600px]' : 'w-full px-2'} mx-auto px-4 md:px-8`}>
        {activeTab === 'plan' ? (
          <>
            <div id="stets">
              <AICoach 
                summary={monthlySummaries[0]} 
                items={items} 
                monthName={months[0].monthName} 
                onAddPartial={handleAddPartial}
              />
            </div>

            <div id="diagnosis">
              <Diagnosis summary={monthlySummaries[0]} monthName={months[0].monthName} />
            </div>

            <div id="blocks">
              {[
                { title: "ENTRADAS (Rendas)", type: CategoryType.INCOME },
                { title: "FATURAS DE CARTÃO", type: CategoryType.CREDIT_CARD },
                { title: "CONTAS FIXAS", subtitle: "Recorrentes, Regulares ou > 12 parcelas", type: CategoryType.FIXED_EXPENSE },
                { title: "CONTAS VARIÁVEIS", type: CategoryType.VARIABLE_EXPENSE },
                { title: "LAZER E GASTOS PESSOAIS", type: CategoryType.PERSONAL_LEISURE }
              ].map(block => (
                <BlockSection 
                  key={block.type} title={block.title} subtitle={block.subtitle} category={block.type} 
                  items={items.filter(i => i.category === block.type)} allCards={allCards}
                  months={months} startMonth={startMonth} onStartMonthChange={setStartMonth}
                  onAddItem={handleAddItem} onUpdateValue={handleUpdateValue} onTogglePaid={handleTogglePaid} 
                  onRemoveItem={handleRemoveItem} onUpdateDescription={handleUpdateDescription} 
                  onReplicateValue={handleReplicateValue} onLinkCard={handleLinkCard}
                />
              ))}
            </div>

            {/* Nova Seção de Resumo Compilado e Acumulado */}
            <div id="summary-section" className="bg-zinc-900 border border-yellow-600/30 rounded-[40px] p-8 mt-12 mb-20 shadow-2xl">
              <h3 className="text-yellow-500 font-black text-xl uppercase italic tracking-tighter mb-8 flex items-center gap-3">
                <i className="fas fa-vault"></i> Bússola do Enriquecimento (12 Meses)
              </h3>

              <div className="overflow-x-auto pb-4">
                <table className="w-full text-left text-sm">
                  <thead>
                    <tr className="text-zinc-500 font-black uppercase text-[10px] tracking-widest border-b border-zinc-800">
                      <th className="p-4 bg-zinc-950/50 rounded-tl-2xl">Indicador</th>
                      {months.map((m, i) => (
                        <th key={i} className={`p-4 text-center ${i === 0 ? 'text-yellow-500 bg-yellow-500/5' : ''}`}>{m.monthName}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    <tr className="border-b border-zinc-800/50 hover:bg-zinc-800/30 transition-colors">
                      <td className="p-4 font-bold text-zinc-300">Total de Entradas</td>
                      {monthlySummaries.map((s, i) => <td key={i} className="p-4 text-center text-green-500 font-mono">{formatCurrency(s.totalIncome)}</td>)}
                    </tr>
                    <tr className="border-b border-zinc-800/50 hover:bg-zinc-800/30 transition-colors">
                      <td className="p-4 font-bold text-zinc-300">Faturas de Cartão</td>
                      {monthlySummaries.map((s, i) => <td key={i} className="p-4 text-center text-orange-400 font-mono">{formatCurrency(s.totalCreditCard)}</td>)}
                    </tr>
                    <tr className="border-b border-zinc-800/50 hover:bg-zinc-800/30 transition-colors">
                      <td className="p-4 font-bold text-zinc-300">Custo Total de Vida</td>
                      {monthlySummaries.map((s, i) => <td key={i} className="p-4 text-center text-red-400 font-mono">{formatCurrency(s.totalCost)}</td>)}
                    </tr>
                    <tr className="border-b-2 border-zinc-800 bg-zinc-950/20">
                      <td className="p-4 font-black text-white uppercase italic">Sobra ou Falta</td>
                      {monthlySummaries.map((s, i) => (
                        <td key={i} className={`p-4 text-center font-black font-mono ${s.balance >= 0 ? 'text-green-400' : 'text-red-500 animate-pulse'}`}>
                          {formatCurrency(s.balance)}
                        </td>
                      ))}
                    </tr>
                    <tr className="bg-yellow-600/5">
                      <td className="p-6 font-black text-yellow-500 uppercase italic text-base">ACUMULADO RICO</td>
                      {monthlySummaries.map((s, i) => (
                        <td key={i} className="p-6 text-center font-black font-mono text-lg text-yellow-500 drop-shadow-lg">
                          {formatCurrency(s.accumulated)}
                        </td>
                      ))}
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </>
        ) : (
          <TetoGastos 
            items={items} 
            currentMonthIdx={currentActualMonth} 
            currentYear={currentActualYear}
            onAddPartial={handleAddPartial}
            onRemovePartial={handleRemovePartial}
          />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { CategoryType, FinanceItem, LinkType } from '../types';
import { formatCurrency, MONTHS_BR } from '../constants';

interface BlockSectionProps {
  title: string;
  subtitle?: string;
  category: CategoryType;
  items: FinanceItem[];
  allCards?: FinanceItem[];
  months: any[];
  startMonth?: number;
  onStartMonthChange?: (monthIdx: number) => void;
  onAddItem: (category: CategoryType) => void;
  onUpdateValue: (id: string, monthIdx: number, value: string) => void;
  onTogglePaid: (id: string, monthIdx: number) => void;
  onRemoveItem: (id: string) => void;
  onUpdateDescription: (id: string, desc: string) => void;
  onReplicateValue: (id: string, monthIdx: number) => void;
  onLinkCard?: (itemId: string, cardId: string, linkType?: LinkType) => void;
}

const BlockSection: React.FC<BlockSectionProps> = ({
  title,
  subtitle,
  category,
  items,
  allCards = [],
  months,
  startMonth,
  onStartMonthChange,
  onAddItem,
  onUpdateValue,
  onTogglePaid,
  onRemoveItem,
  onUpdateDescription,
  onReplicateValue,
  onLinkCard
}) => {
