                        className="bg-transparent border-none focus:ring-0 text-center font-bold uppercase cursor-pointer hover:text-yellow-600 transition-colors p-0 appearance-none pr-4"
                        value={startMonth}
                        onChange={(e) => onStartMonthChange(parseInt(e.target.value))}
