import React, { useState, useEffect } from 'react';
import { FinanceItem, PartialExpense, CategoryType } from '../types';
import { formatCurrency } from '../constants';

interface TetoGastosProps {
  items: FinanceItem[];
  currentMonthIdx: number;
  currentYear: number;
  onAddPartial: (itemId: string, expense: PartialExpense) => void;
  onRemovePartial: (itemId: string, expenseId: string) => void;
}

interface ColumnData {
  id: string;
  title: string;
  linkedItemId: string;
}

const TetoGastos: React.FC<TetoGastosProps> = ({ items, currentMonthIdx, currentYear, onAddPartial, onRemovePartial }) => {
  const monthKey = `${currentYear}-${currentMonthIdx}`;

  const [columns, setColumns] = useState<ColumnData[]>(() => {
    const saved = localStorage.getItem('teto_columns_v3');
    return saved ? JSON.parse(saved) : [
      { id: '1', title: 'SUPERMERCADO', linkedItemId: '' },
      { id: '2', title: 'GASOLINA', linkedItemId: '' },
      { id: '3', title: 'LAZER', linkedItemId: '' },
      { id: '4', title: 'EXTRAS', linkedItemId: '' }
    ];
  });

  useEffect(() => {
    localStorage.setItem('teto_columns_v3', JSON.stringify(columns));
  }, [columns]);

  const addColumn = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    setColumns([...columns, { id: newId, title: `NOVA DESPESA`, linkedItemId: '' }]);
  };

  const removeColumn = (id: string) => {
    if (columns.length <= 1) return;
    setColumns(columns.filter(c => c.id !== id));
  };

  const updateColumn = (id: string, field: keyof ColumnData, value: string) => {
    setColumns(columns.map(c => c.id === id ? { ...c, [field]: value } : c));
  };

  const handleValueEntry = (itemId: string, value: string) => {
    if (!itemId || value === '' || isNaN(parseFloat(value))) return;
    const expense: PartialExpense = {
      id: Math.random().toString(36).substr(2, 9),
      date: new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }),
      description: 'Gasto mensal',
      value: parseFloat(value)
    };
    onAddPartial(itemId, expense);
  };

  return (
    <div className="p-2 md:p-6 animate-in fade-in zoom-in-95 duration-500">
      <div className="mb-6 flex justify-end">
        <button 
          onClick={addColumn}
          className="bg-yellow-600 hover:bg-yellow-500 text-black font-black px-6 py-3 rounded-xl text-xs uppercase transition-all shadow-lg flex items-center gap-2"
        >
          <i className="fas fa-plus-circle"></i> Adicionar Coluna
        </button>
      </div>

      <div className="flex gap-4 overflow-x-auto pb-8 pt-2 px-2 scrollbar-thin scrollbar-thumb-yellow-600 scrollbar-track-zinc-900">
        {columns.map((col) => {
          const linkedItem = items.find(i => i.id === col.linkedItemId);
          // Busca o valor planejado para o mês atual
          const teto = linkedItem ? linkedItem.values[0] : 0;
          const partials = linkedItem?.partialExpenses?.[monthKey] || [];
          const totalSpent = partials.reduce((acc, p) => acc + p.value, 0);
          const isOverLimit = totalSpent > teto && teto > 0;

          return (
            <div key={col.id} className="min-w-[260px] flex-shrink-0 flex flex-col group relative transition-all duration-300">

              <div className="bg-yellow-500 rounded-t-2xl p-1 border-b border-yellow-600">
                <select 
                  className="w-full bg-transparent border-none text-[10px] font-black uppercase p-3 text-center text-black outline-none cursor-pointer"
                  value={col.linkedItemId}
                  onChange={(e) => updateColumn(col.id, 'linkedItemId', e.target.value)}
                >
                  <option value="" className="bg-yellow-500">VINCULAR AO ORÇAMENTO</option>
                  {/* Agora permite vincular Fixas, Variáveis e também Lazer/Pessoal */}
                  {items.filter(i => 
                    i.category === CategoryType.FIXED_EXPENSE || 
                    i.category === CategoryType.VARIABLE_EXPENSE || 
                    i.category === CategoryType.PERSONAL_LEISURE
                  ).map(i => (
                    <option key={i.id} value={i.id} className="bg-yellow-100">
                      [{i.category === CategoryType.PERSONAL_LEISURE ? 'LAZER' : 'ORÇAM.'}] {i.description || 'Sem nome'}
                    </option>
                  ))}
                </select>
              </div>

              <div className="bg-zinc-900 border-x border-zinc-800">
                <input 
                  type="text" 
                  value={col.title}
                  onChange={(e) => updateColumn(col.id, 'title', e.target.value)}
                  className="w-full bg-transparent border-none text-center font-black text-[11px] uppercase p-3 text-white outline-none tracking-widest"
                  placeholder="NOME DA COLUNA"
                />
              </div>

              <div className={`border-x border-zinc-700 p-4 text-center ${isOverLimit ? 'bg-red-950/30' : 'bg-zinc-800'}`}>
                <p className="text-[8px] font-black text-zinc-400 uppercase tracking-widest mb-1 italic">Teto Planejado</p>
                <div className={`text-lg font-black font-mono ${isOverLimit ? 'text-red-500 animate-pulse' : 'text-yellow-500'}`}>
                  {formatCurrency(teto)}
                </div>
              </div>

              <div className="bg-white border-x border-zinc-200 shadow-inner">
                <div className="relative">
                   <div className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-300 text-[10px] font-bold">R$</div>
                   <input 
                    type="number" 
                    placeholder="Digitar valor e ENTER"
                    className="w-full p-4 pl-8 text-center text-sm outline-none bg-transparent focus:bg-yellow-50/50 font-black text-zinc-900 transition-all placeholder:text-zinc-300 placeholder:font-normal"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        handleValueEntry(col.linkedItemId, e.currentTarget.value);
                        e.currentTarget.value = '';
                      }
                    }}
                  />
                </div>
              </div>

              <div className="flex-grow flex flex-col bg-white border-x border-zinc-100 min-h-[350px]">
                {Array.from({ length: Math.max(12, partials.length) }).map((_, idx) => {
                  const p = partials[idx];
                  return (
                    <div key={idx} className={`border-b border-zinc-50 h-10 flex items-center justify-center relative group/row ${p ? 'hover:bg-zinc-50' : ''}`}>
                      {p ? (
                        <div className="w-full flex justify-between items-center px-4 animate-in fade-in">
                          <span className="text-[9px] text-zinc-400 font-bold uppercase">{p.date}</span>
                          <span className="text-xs font-black text-zinc-800 font-mono">{formatCurrency(p.value)}</span>
                          <button 
                            onClick={() => onRemovePartial(col.linkedItemId, p.id)}
                            className="opacity-0 group-hover/row:opacity-100 text-red-500 transition-all p-1"
                          >
                            <i className="fas fa-times-circle"></i>
                          </button>
                        </div>
                      ) : (
                        <div className="w-full h-[1px] bg-zinc-50/50 mx-4"></div>
                      )}
                    </div>
                  );
                })}
              </div>

              <div className={`p-5 rounded-b-2xl border border-zinc-200 text-center shadow-lg transition-all ${isOverLimit ? 'bg-red-50' : 'bg-zinc-900'}`}>
                <p className={`text-[9px] font-black uppercase mb-1 ${isOverLimit ? 'text-red-600' : 'text-zinc-500'}`}>Total Lançado</p>
                <p className={`text-xl font-black font-mono tracking-tighter ${isOverLimit ? 'text-red-600' : 'text-yellow-500'}`}>
                  {formatCurrency(totalSpent)}
                </p>
              </div>

              <button 
                onClick={() => removeColumn(col.id)}
                className="absolute -top-3 -right-3 w-8 h-8 bg-zinc-900 text-zinc-500 hover:text-red-500 rounded-full border border-zinc-800 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all shadow-xl z-20"
              >
                <i className="fas fa-trash-alt text-xs"></i>
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default TetoGastos;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { SummaryData, FinanceItem, CategoryType, PartialExpense } from '../types';
import { IDEAL_LIMITS, formatCurrency } from '../constants';

interface AICoachProps {
  summary: SummaryData;
  items: FinanceItem[];
  monthName: string;
  onAddPartial: (itemId: string, expense: PartialExpense) => void;
}

const AICoach: React.FC<AICoachProps> = ({ summary, items, monthName, onAddPartial }) => {
  const [prompt, setPrompt] = useState('');
  const [response, setResponse] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.lang = 'pt-BR';
      recognitionRef.current.interimResults = true;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = Array.from(event.results)
          .map((result: any) => result[0])
          .map((result: any) => result.transcript)
          .join('');
        setPrompt(transcript);

        if (event.results[0].isFinal) {
          setIsListening(false);
          setTimeout(() => analyzeOrAction(transcript), 500);
        }
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current.onerror = (event: any) => {
        console.error("Erro no reconhecimento de voz:", event.error);
        setIsListening(false);
      };
    }
  }, []);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setPrompt('');
      recognitionRef.current?.start();
      setIsListening(true);
    }
  };

  const analyzeOrAction = async (textToProcess?: string) => {
    const finalPrompt = textToProcess || prompt;
    if (!finalPrompt.trim()) return;

    setLoading(true);
    setResponse(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const fixedPercent = (summary.totalFixed / summary.totalIncome) * 100;
    const leisurePercent = (summary.totalLeisure / summary.totalIncome) * 100;

    // Agora incluímos também itens de Lazer para o Stets poder lançar gastos neles
    const availableItems = items
      .filter(i => 
        i.category === CategoryType.FIXED_EXPENSE || 
        i.category === CategoryType.VARIABLE_EXPENSE || 
        i.category === CategoryType.PERSONAL_LEISURE
      )
      .map(i => ({ id: i.id, description: i.description, category: i.category }));

    const systemInstruction = `
      Seu nome é Stets. Você é o mentor e assistente pessoal de finanças do método "RICO nessa vida".
      Sua missão é:
      1. ANALISAR: Se o usuário perguntar sobre a vida financeira (ex: "Stets, como estou indo?"), use os dados: Renda ${formatCurrency(summary.totalIncome)}, Fixos ${fixedPercent.toFixed(1)}% (ideal 55%), Lazer ${leisurePercent.toFixed(1)}% (ideal 15%). 
      2. LANÇAR GASTOS: Se o usuário disser que gastou algo (ex: "Stets, gastei 50 reais com cinema"), identifique o VALOR e a CATEGORIA/ITEM mais provável entre os IDs disponíveis: ${JSON.stringify(availableItems)}.

      IMPORTANTE: Para lançamentos de gastos detectados no texto, chame SEMPRE a função 'registrar_gasto'.
      Ao responder, apresente-se como Stets. Seu tom deve ser sofisticado, direto e encorajador. Você não apenas organiza, você lidera o usuário rumo à riqueza.
    `;

    const registrarGastoTool = {
      name: 'registrar_gasto',
      parameters: {
        type: Type.OBJECT,
        description: 'Registra um novo gasto nas planilhas de lançamento diário (Gastos Frequentes)',
        properties: {
          itemId: { type: Type.STRING, description: 'O ID do item/coluna correspondente da lista disponível' },
          valor: { type: Type.NUMBER, description: 'O valor numérico do gasto sem R$' },
          categoriaEncontrada: { type: Type.STRING, description: 'Nome do item ou categoria identificada para feedback amigável' }
        },
        required: ['itemId', 'valor', 'categoriaEncontrada']
      }
    };

    try {
      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: finalPrompt,
        config: {
          systemInstruction: systemInstruction,
          tools: [{ functionDeclarations: [registrarGastoTool] }],
        }
      });

      const functionCalls = result.functionCalls;

      if (functionCalls && functionCalls.length > 0) {
        const call = functionCalls[0];
        if (call.name === 'registrar_gasto') {
          const { itemId, valor, categoriaEncontrada } = call.args as any;

          const expense: PartialExpense = {
            id: Math.random().toString(36).substr(2, 9),
            date: new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }),
            description: 'Lançamento via Stets',
            value: valor
          };

          onAddPartial(itemId, expense);
          setResponse(`✅ **Aqui é o Stets.**\n\nLançamento de **${formatCurrency(valor)}** processado com sucesso em **${categoriaEncontrada}**. Sua disciplina é o caminho para o topo!`);
          setPrompt('');
        }
      } else {
        setResponse(result.text || "Estou à disposição. Como posso ajudar no seu planejamento hoje?");
      }
    } catch (error) {
      setResponse("Tive um problema momentâneo em processar essa informação. Pode repetir o comando para o Stets?");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-[#0a0a0a] border border-zinc-800 rounded-3xl p-6 mb-8 shadow-2xl relative overflow-hidden group">
      <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform">
        <i className="fas fa-user-tie text-8xl text-yellow-500"></i>
      </div>

      <div className="relative z-10">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className={`w-10 h-10 ${isListening ? 'bg-red-500 animate-ping' : 'bg-yellow-500'} rounded-full flex items-center justify-center transition-colors shadow-lg shadow-yellow-500/20`}>
              <i className={`fas ${isListening ? 'fa-microphone' : 'fa-brain'} text-black`}></i>
            </div>
            <div>
              <h3 className="text-white font-black text-xl uppercase italic tracking-tighter leading-none">Stets - Seu Mentor</h3>
              <p className="text-yellow-500/50 text-[10px] font-bold uppercase tracking-widest mt-1">
                {isListening ? 'Stets está ouvindo com atenção...' : 'Envie um comando para Stets'}
              </p>
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-4">
          <div className="relative flex gap-2">
            <div className="relative flex-grow">
              <input 
                type="text" 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && analyzeOrAction()}
                placeholder={isListening ? 'Pode falar...' : 'Ex: "Lançar 50 reais em cinema", ou peça um diagnóstico financeiro.'}
                className={`w-full bg-zinc-900 border ${isListening ? 'border-red-500/50 ring-1 ring-red-500/20' : 'border-zinc-800'} rounded-2xl px-5 py-4 text-white text-sm outline-none focus:border-yellow-500 transition-all shadow-inner`}
              />
              <button 
                onClick={toggleListening}
                className={`absolute right-3 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isListening ? 'bg-red-500 text-white shadow-lg shadow-red-500/40' : 'text-zinc-500 hover:text-yellow-500 hover:bg-zinc-800'}`}
                title="Falar com Stets"
              >
                <i className={`fas ${isListening ? 'fa-stop' : 'fa-microphone'} text-lg`}></i>
              </button>
            </div>

            <button 
              onClick={() => analyzeOrAction()}
              disabled={loading || isListening}
              className="bg-gradient-to-br from-yellow-400 to-yellow-600 hover:from-yellow-300 hover:to-yellow-500 text-black font-black px-8 rounded-2xl text-xs uppercase transition-all disabled:opacity-50 shadow-lg active:scale-95"
            >
              {loading ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-paper-plane"></i>}
            </button>
          </div>

          {response && (
            <div className="mt-2 bg-zinc-900/80 border border-zinc-800 p-5 rounded-2xl text-zinc-300 text-sm leading-relaxed animate-in zoom-in-95 duration-300">
              <div className="prose prose-invert max-w-none prose-p:my-1">
                {response.split('\n').map((line, i) => (
                  <p key={i}>{line}</p>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AICoach;

